const p = `<h2>\u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB</h2>
<p>\u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u0986\u09B6\u09C7\u09AA\u09BE\u09B6\u09C7 \u09A5\u09BE\u0995\u09C7 \u09A8\u09BE, \u09A4\u09AC\u09C7 \u0986\u09AE\u09B0\u09BE \u09A8\u09BF\u09B0\u09BE\u09AA\u09A6\u09C7 \u09AC\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09BF \u09AF\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09AC\u09BE\u099C\u09BE\u09B0\u09C7 \u0986\u09B8\u09BE\u09B0 \u09AA\u09B0 \u09A5\u09C7\u0995\u09C7 \u0985\u09A8\u09C7\u0995 \u09AC\u09C7\u09B6\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964. \u098F\u09AC\u0982 \u098F\u099F\u09BF \u09B8\u09CD\u09AC\u09B2\u09CD\u09AA \u099A\u09BE\u09B9\u09BF\u09A6\u09BE \u09AC\u09BE \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u09C7\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u09A8\u09AF\u09BC, \u098F\u09AC\u0982 \u098F\u0996\u09A8 2023 \u09B8\u09BE\u09B2\u09C7, \u0986\u09AE\u09BE\u09A6\u09C7\u09B0 \u0995\u09BE\u099B\u09C7 1000 \u098F\u09AC\u0982 1000 \u098F\u09B0 \u09A5\u09C7\u0995\u09C7 \u09AC\u09BE\u099B\u09BE\u0987 \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09B0\u09AF\u09BC\u09C7\u099B\u09C7 - \u098F\u099F\u09BF \u0995\u09C7\u09AC\u09B2\u09AE\u09BE\u09A4\u09CD\u09B0 \u0986\u09AA\u09A8\u09BF \u0995\u09C0 \u09AA\u099B\u09A8\u09CD\u09A6 \u0995\u09B0\u09C7\u09A8 \u098F\u09AC\u0982 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0986\u09AA\u09A8\u09BF \u0995\u09CB\u09A8 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u0997\u09C1\u09B2\u09BF \u09A6\u09C7\u0996\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A4\u09BE\u09B0 \u09AC\u09BF\u09B7\u09AF\u09BC\u0964.</p>
<p>\u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09B0\u09BE \u09B8\u09B0\u09CD\u09AC\u09A6\u09BE \u09A8\u09A4\u09C1\u09A8 \u0995\u09BF\u099B\u09C1 \u0996\u09C1\u0981\u099C\u099B\u09C7\u09A8, \u09AF\u09BE \u0997\u09C7\u09AE\u09BF\u0982 \u0985\u09AD\u09BF\u099C\u09CD\u099E\u09A4\u09BE\u0995\u09C7 \u0986\u09B0\u0993 \u09AD\u09BE\u09B2 \u098F\u09AC\u0982 \u0986\u09B0\u0993 \u0985\u09CD\u09AF\u09BE\u0995\u09CD\u09B8\u09C7\u09B8\u09AF\u09CB\u0997\u09CD\u09AF \u0995\u09B0\u09A4\u09C7 \u09B8\u09BE\u09B9\u09BE\u09AF\u09CD\u09AF \u0995\u09B0\u09AC\u09C7\u0964. \u09AA\u09CD\u09B2\u09C7\u09AF\u09BC\u09BE\u09B0\u0995\u09C7 \u098F\u0995\u099F\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09B0 \u09A8\u09BF\u0996\u09C1\u0981\u09A4 \u09AE\u099C\u09BE\u09B0 \u0989\u09AA\u09B0 \u09AB\u09CB\u0995\u09BE\u09B8 \u0995\u09B0\u09BE\u09B0 \u0985\u09A8\u09C1\u09AE\u09A4\u09BF \u09A6\u09C7\u0993\u09AF\u09BC\u09BE, \u098F\u099F\u09BF \u09A0\u09BF\u0995, \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u09A8\u09BF\u099C\u09C7\u0987\u0964.</p>

<div class="other-info">
  <p>\u098F\u0987 \u0995\u09BE\u09B0\u09A3\u09C7\u0987 \u0986\u09AE\u09B0\u09BE \u098F\u0996\u09A8 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u098F\u0995\u099F\u09BF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09AC\u09BE \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u099C\u09C1\u09AF\u09BC\u09BE \u09AC\u09BE \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AF\u09BE \u099C\u09BE\u09A8\u09BE \u09A6\u09B0\u0995\u09BE\u09B0 \u09A4\u09BE \u09AC\u09B2\u09A4\u09C7 \u09AF\u09BE\u099A\u09CD\u099B\u09BF, \u0986\u09AA\u09A8\u09BF \u098F\u099F\u09BF\u0995\u09C7 \u09AF\u09BE\u0987 \u09AC\u09B2\u09C1\u09A8 \u09A8\u09BE \u0995\u09C7\u09A8\u0964.</p>
  <h2>\u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09BF?</h2>
  <p>\u0986\u09AA\u09A8\u09BF \u0995\u09CB\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09A4\u09BE \u09A8\u09BF\u09AF\u09BC\u09C7 \u0986\u09B2\u09CB\u099A\u09A8\u09BE \u0995\u09B0\u09BE\u09B0 \u0986\u0997\u09C7, \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AA\u09CD\u09B0\u09A5\u09AE\u09C7 \u09AC\u09C1\u099D\u09A4\u09C7 \u09B9\u09AC\u09C7 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09C0 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u09AF\u0996\u09A8 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09CD\u09B0\u09BF\u09AF\u09BC \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u0996\u09C7\u09B2\u09AC\u09C7\u09A8 \u09A4\u0996\u09A8 \u09B2\u09CB\u0995\u09C7\u09B0\u09BE \u0995\u09C7\u09A8 \u098F\u0987 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u099F\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AA\u099B\u09A8\u09CD\u09A6 \u0995\u09B0\u09C7\u09F7.</p>
  <p>\u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u098F\u09AC\u0982 \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB\u0995\u09BE\u09B0\u09C7\u09A8\u09CD\u09B8\u09BF\u0997\u09C1\u09B2\u09BF \u0997\u09A4 \u0995\u09AF\u09BC\u09C7\u0995 \u09AC\u099B\u09B0 \u09A7\u09B0\u09C7 \u09A8\u09BF\u099C\u09C7\u09A6\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u0995\u099F\u09BF \u09AC\u09A1\u09BC \u09A8\u09BE\u09AE \u09A4\u09C8\u09B0\u09BF \u0995\u09B0\u099B\u09C7\u0964. \u09AF\u0996\u09A8 \u098F\u099F\u09BF \u09B6\u09C1\u09B0\u09C1 \u09B9\u09AF\u09BC\u09C7\u099B\u09BF\u09B2, \u09A4\u0996\u09A8 \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0995\u09C7\u09A8\u09BE \u098F\u0995\u099F\u09BF \u099D\u09C1\u0981\u0995\u09BF \u099B\u09BF\u09B2 \u098F\u09AC\u0982 \u09AF\u09BE\u09B0\u09BE \u099D\u09C1\u0981\u0995\u09BF \u09A8\u09BF\u099A\u09CD\u099B\u09C7\u09A8 \u09A4\u09BE\u09B0\u09BE\u0987 \u098F\u0996\u09A8 \u098F\u099F\u09BF \u09A5\u09C7\u0995\u09C7 \u0989\u09AA\u0995\u09C3\u09A4 \u09B9\u099A\u09CD\u099B\u09C7\u09A8\u0964. \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09A5\u09C7\u0995\u09C7 \u09B8\u09AE\u09CD\u09AD\u09BE\u09AC\u09CD\u09AF \u09A8\u09CD\u09AF\u09BE\u09AF\u09CD\u09AF \u0986\u09AF\u09BC \u09B9\u09AF\u09BC\u09C7\u099B\u09C7 \u09AC\u09BE\u099C\u09BE\u09B0\u09C7 \u0993\u09A0\u09BE-\u09A8\u09BE\u09AE\u09BE \u0995\u09B0\u09C7, \u098F\u09AC\u0982 \u098F\u09B0 \u09B8\u09AC\u09A5\u09C7\u0995\u09C7 \u09AD\u09BE\u09B2\u09CB - \u0986\u09AA\u09A8\u09BF \u098F\u099F\u09BF \u09B8\u09AE\u09CD\u09AA\u09C2\u09B0\u09CD\u09A3 \u09AC\u09C7\u09A8\u09BE\u09AE\u09C7 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964.</p>
  <p>\u098F\u099F\u09BF \u09A4\u0996\u09A8 \u098F\u0995\u099F\u09BF \u099D\u09C1\u0981\u0995\u09BF \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u099C \u0986\u09AA\u09A8\u09BF \u0985\u09A8\u09CD\u09AF \u09AF\u09C7\u0995\u09CB\u09A8\u09CB \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u09C7\u09B0 \u09AE\u09A4\u09CB \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964. \u0995\u09AF\u09BC\u09C7\u0995\u099C\u09A8 \u098F\u099F\u09BF \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u099B\u09C7 \u09A8\u09BE, \u09A4\u09AC\u09C7 BTC \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u098F\u0995\u099F\u09BF \u09AC\u09A1\u09BC \u09B9\u09BF\u099F \u098F\u09AC\u0982 \u0997\u09A4 5+ \u09AC\u099B\u09B0 \u09A7\u09B0\u09C7 \u098F\u099F\u09BF \u0995\u09CD\u09B0\u09AE\u09BE\u0997\u09A4 \u09AC\u09C3\u09A6\u09CD\u09A7\u09BF \u09AA\u09C7\u09AF\u09BC\u09C7\u099B\u09C7\u0964.</p>
  <p>\u098F\u09AC\u0982 \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3\u09AD\u09BE\u09AC\u09C7 \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u09AC\u09CB\u09A8\u09BE\u09B8 \u09AC\u09BE \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA \u09B9\u09BF\u09B8\u09BE\u09AC\u09C7 \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u09AF\u09BE \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09AC\u09C7\u09B6\u09BF \u09AA\u099B\u09A8\u09CD\u09A6 \u09A4\u09BE \u09B9\u09B2 \u0986\u09AA\u09A8\u09BF \u09B8\u09B9\u099C\u09C7\u0987 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AC\u09CD\u09AF\u09BE\u0999\u09CD\u0995 \u0985\u09CD\u09AF\u09BE\u0995\u09BE\u0989\u09A8\u09CD\u099F\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0985\u09CD\u09AF\u09BE\u0995\u09BE\u0989\u09A8\u09CD\u099F \u09B2\u09BF\u0999\u09CD\u0995 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BE\u09B0 \u09B6\u09C0\u09B0\u09CD\u09B7 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AE\u099C\u09BE\u09A4\u09C7 \u09B8\u09B0\u09BE\u09B8\u09B0\u09BF \u098F\u09AC\u0982 \u09A4\u09BE\u09A4\u09CD\u0995\u09CD\u09B7\u09A3\u09BF\u0995 \u0985\u09CD\u09AF\u09BE\u0995\u09CD\u09B8\u09C7\u09B8 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964.</p>

  <h2>\u0986\u09AA\u09A8\u09BF \u0995\u09BF \u09B8\u09AE\u09B8\u09CD\u09A4 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u099C\u09C1\u09AF\u09BC\u09BE \u09B8\u09BE\u0987\u099F\u09C7 \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8?</h2>
  <p>\u09B8\u09AE\u09B8\u09CD\u09A4 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09B0\u09BE \u09B8\u09CD\u09AC\u09AA\u09CD\u09A8 \u09A6\u09C7\u0996\u09AC\u09C7 \u09AF\u09C7 \u0986\u09AA\u09A8\u09BF \u09AF\u09C7 \u09B8\u09AE\u09B8\u09CD\u09A4 \u0986\u09B2\u09BE\u09A6\u09BE \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09BE\u09A8 \u09B8\u09C7\u0997\u09C1\u09B2\u09BF \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u099C\u09AE\u09BE \u098F\u09AC\u0982 \u0989\u09A4\u09CD\u09A4\u09CB\u09B2\u09A8\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u098F\u09AC\u0982 \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u0985\u09A8\u09C1\u09AE\u09A4\u09BF \u09A6\u09C7\u09AC\u09C7\u0964. \u09A6\u09C1\u09B0\u09CD\u09AD\u09BE\u0997\u09CD\u09AF\u0995\u09CD\u09B0\u09AE\u09C7, \u09A6\u09C1\u0983\u0996\u099C\u09A8\u0995 \u09B8\u09A4\u09CD\u09AF \u09B9\u09B2 \u09AF\u09C7 \u0996\u09C1\u09AC \u0995\u09AE \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u098F\u099F\u09BF \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09C7\u0964. \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09AD\u09BE\u09B2 \u0996\u09AC\u09B0 \u09B9\u09B2 \u09B6\u09C0\u09B0\u09CD\u09B7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF\u09A4\u09C7 \u098F\u0995 \u09AC\u09BE \u0985\u09A8\u09CD\u09AF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09A5\u09BE\u0995\u09AC\u09C7 \u09AF\u09BE \u0986\u09AA\u09A8\u09BF \u0985\u09A8\u09CD\u09A4\u09A4 \u0986\u09AE\u09BE\u09A8\u09A4\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964. \u09AF\u0996\u09A8 \u099F\u09BE\u0995\u09BE \u09A4\u09CB\u09B2\u09BE\u09B0 \u0995\u09A5\u09BE \u0986\u09B8\u09C7, \u09A4\u0996\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09BE\u0993\u09AF\u09BC\u09BE \u098F\u0995\u099F\u09C1 \u0995\u09A0\u09BF\u09A8\u0964. \u09B8\u09AE\u09CD\u09AD\u09AC\u09A4, \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u0997\u09C1\u09B2\u09BF\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u098F\u0995\u099F\u09BF \u09AC\u09C7\u099B\u09C7 \u09A8\u09BF\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964. \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u098F\u09AC\u0982 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB\u09B0 \u09B8\u09BE\u09A5\u09C7 \u098F\u0995\u09A4\u09CD\u09B0\u09BF\u09A4 \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09AC\u09C7\u09B6\u09BF \u09AA\u09BE\u0993\u09AF\u09BC\u09BE \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA \u09B9\u09B2 \u09B8\u09B0\u09BE\u09B8\u09B0\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09AC\u09CD\u09AF\u09BE\u0999\u09CD\u0995 \u0985\u09CD\u09AF\u09BE\u0995\u09BE\u0989\u09A8\u09CD\u099F\u09C7 \u098F\u0995\u099F\u09BF \u09AC\u09CD\u09AF\u09BE\u0999\u09CD\u0995 \u09B8\u09CD\u09A5\u09BE\u09A8\u09BE\u09A8\u09CD\u09A4\u09B0\u09F7.</p>
  <p>\u09B8\u09C7\u0996\u09BE\u09A8\u09C7 \u09A8\u09A4\u09C1\u09A8\u09A6\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF, \u0986\u09AA\u09A8\u09BF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09C7 \u098F\u09AE\u09A8 \u09AC\u09C7\u099F\u09BF\u0982 \u09B8\u09BE\u0987\u099F\u0997\u09C1\u09B2\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C7 \u09A6\u09C7\u0996\u09A4\u09C7 \u099A\u09BE\u09A8 \u0995\u09BF\u09A8\u09BE \u09A4\u09BE \u09A6\u09C7\u0996\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09AE\u09B0\u09BE \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF\u09B0 \u099C\u09A8\u09CD\u09AF \u0995\u09AF\u09BC\u09C7\u0995\u099F\u09BF \u09A8\u09BE\u09AE \u099B\u09C7\u09A1\u09BC\u09C7 \u09A6\u09C7\u09AC\u0964. \u0986\u09AE\u09BE\u09A6\u09C7\u09B0 \u0986\u099B\u09C7 Doge Casino, Shiba Casino, \u098F\u09AC\u0982 Solana Casino, \u098F\u09AC\u0982 \u098F\u0997\u09C1\u09B2\u09CB \u09B8\u09AC\u0987 \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC\u09C7\u09B0 \u09AE\u09C2\u09B2\u09CD\u09AF\u09AC\u09BE\u09A8. \u09A4\u09BE\u09B0\u09BE \u09B8\u09C7\u0987 \u0989\u09A4\u09CD\u09A4\u09C7\u099C\u09A8\u09BE \u09A8\u09BF\u09AF\u09BC\u09C7 \u0986\u09B8\u09AC\u09C7 \u09AF\u09BE \u0986\u09AA\u09A8\u09BF \u09B8\u0995\u09B2\u09C7\u0987 \u0996\u09C1\u0981\u099C\u099B\u09C7\u09A8\u0964. \u0986\u09AA\u09A8\u09BF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09A6\u09BF\u09AF\u09BC\u09C7 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 - \u098F\u09AC\u0982 \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09AD\u09BE\u09B2\u09CB \u09A6\u09BF\u0995 \u09B9\u09B2 \u09A4\u09BE\u09B0\u09BE \u09B8\u09AC\u09BE\u0987 \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u09AC\u0982 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u099C\u09C1\u09AF\u09BC\u09BE\u09B0 \u099C\u0997\u09A4\u09C7 \u09AF\u09CB\u0997\u09A6\u09BE\u09A8\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u098F\u0995\u099F\u09BF \u09A6\u09C1\u09B0\u09CD\u09A6\u09BE\u09A8\u09CD\u09A4 \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u09AC\u09CB\u09A8\u09BE\u09B8 \u09A6\u09BF\u099A\u09CD\u099B\u09C7\u0964.</p>
  
  <h2>\u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u099C\u09C1\u09AF\u09BC\u09BE\u09B0 \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE \u0995\u09BF?</h2>
  <ul>
    <li>\u09A8\u09BE\u09AE \u09AA\u09CD\u09B0\u0995\u09BE\u09B6 \u09A8\u09BE \u0995\u09B0\u09BE \u2013 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09AC\u09BE\u099C\u09BE\u09B0\u09C7 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC, \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u098F\u09AE\u09A8 \u09A4\u09A5\u09CD\u09AF \u09A6\u09C7\u0993\u09AF\u09BC\u09BE\u09B0 \u09A6\u09B0\u0995\u09BE\u09B0 \u09A8\u09C7\u0987 \u09AF\u09BE \u0986\u09AA\u09A8\u09BE\u09B0 \u0995\u09BE\u099B\u09C7 \u09AB\u09BF\u09B0\u09C7 \u09AF\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964. \u0986\u09AA\u09A8\u09BF \u0995\u09AE\u09CD\u09AA\u09BF\u0989\u099F\u09BE\u09B0 \u09B8\u09CD\u0995\u09CD\u09B0\u09BF\u09A8\u09C7\u09B0 \u09AA\u09BF\u099B\u09A8\u09C7 100% \u09B2\u09C1\u0995\u09BF\u09AF\u09BC\u09C7 \u09B0\u09BE\u0996\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A5\u09AE \u09A8\u09BE\u09AE\u09C7\u09B0 \u09AE\u09A4\u09CB \u0995\u0996\u09A8\u0993 \u099B\u09BE\u09A1\u09BC\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964. \u0985\u09A8\u09C7\u0995\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u0987 \u09A7\u09B0\u09A8\u09C7\u09B0 \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u099F\u09BF \u09B6\u09C0\u09B0\u09CD\u09B7-\u09AC\u09BF\u0995\u09CD\u09B0\u09AF\u09BC \u09AA\u09AF\u09BC\u09C7\u09A8\u09CD\u099F\u0964.</li>
    <li>\u09AC\u09BF\u09B6\u09CD\u09AC\u09AC\u09CD\u09AF\u09BE\u09AA\u09C0 \u0985\u09CD\u09AF\u09BE\u0995\u09CD\u09B8\u09C7\u09B8 - \u09AF\u09C7\u09AE\u09A8 \u0986\u09AE\u09B0\u09BE \u099C\u09BE\u09A8\u09BF, \u0985\u09A8\u09C7\u0995\u0997\u09C1\u09B2\u09BF \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u0997\u09C1\u09B2\u09BF \u0995\u09C7\u09AC\u09B2\u09AE\u09BE\u09A4\u09CD\u09B0 \u0995\u09BE\u09B0\u0993 \u0995\u09BE\u09B0\u0993 \u099C\u09A8\u09CD\u09AF \u0989\u09AA\u09B2\u09AC\u09CD\u09A7, \u09B8\u0995\u09B2\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09A8\u09AF\u09BC, \u098F\u09AC\u0982 \u098F\u099F\u09BF \u0996\u09C1\u09AC \u09B9\u09A4\u09BE\u09B6\u09BE\u099C\u09A8\u0995 \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7 \u098F\u09AC\u0982 \u0995\u09BF\u099B\u09C1 \u09A6\u09C7\u09B6\u09C7\u09B0 \u0995\u09BF\u099B\u09C1 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u099A\u09CD\u09AF\u09BE\u09B2\u09C7\u099E\u09CD\u099C\u09BF\u0982 \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7 - \u0995\u09BE\u09B0\u09A3 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u0997\u09C1\u09B2\u09BF\u09B0 \u09B8\u09C0\u09AE\u09BE\u09AC\u09A6\u09CD\u09A7\u09A4\u09BE\u0997\u09C1\u09B2\u09BF \u09A4\u09BE\u09A6\u09C7\u09B0 \u0996\u09C7\u09B2\u09BE \u09A5\u09C7\u0995\u09C7 \u0997\u09C1\u09B0\u09C1\u09A4\u09B0\u09AD\u09BE\u09AC\u09C7 \u0985\u09AC\u09B0\u09C1\u09A6\u09CD\u09A7 \u0995\u09B0\u099B\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u098F\u09AC\u0982 \u0997\u09C7\u09AE \u09A4\u09BE\u09B0\u09BE \u0996\u09C7\u09B2\u09A4\u09C7 \u099A\u09BE\u09AF\u09BC\u0964. \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u098F\u09AC\u0982 \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF\u09B0 \u09B8\u09BE\u09A5\u09C7, \u09A4\u09BE\u09B0\u09BE \u098F\u0987 \u09B8\u09C0\u09AE\u09BE\u099F\u09BF \u09B8\u09B0\u09BF\u09AF\u09BC\u09C7 \u09AB\u09C7\u09B2\u09AC\u09C7 \u098F\u09AC\u0982 \u09A4\u09BE\u09A6\u09C7\u09B0 \u09AE\u099C\u09BE \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09B0 \u0995\u09CB\u09A5\u09BE\u0993 \u09A4\u09BE\u0995\u09BE\u09A4\u09C7 \u09B9\u09AC\u09C7 \u09A8\u09BE\u0964.</li>
    <li>\u09AF\u09BE\u099A\u09BE\u0987\u0995\u09B0\u09A3 - \u098F\u0995\u099F\u09BF \u0986\u09B8\u09B2 \u09AA\u09BE\u09B0\u09CD\u099F\u09BF \u09AA\u09C2\u09AA\u09BE\u09B0 \u09B9\u09B2 \u09AF\u0996\u09A8 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AE\u099C\u09BE \u0985\u09CD\u09AF\u09BE\u0995\u09CD\u09B8\u09C7\u09B8 \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0985\u09A8\u09C7\u0995 \u09A4\u09A5\u09CD\u09AF \u09AA\u09C2\u09B0\u09A3 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964. \u09B8\u09B9\u099C \u0989\u09A4\u09CD\u09A4\u09B0 \u09B9\u09B2 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE, \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0986\u09B0 \u098F\u0987 \u0985\u09AD\u09BF\u099C\u09CD\u099E\u09A4\u09BE\u09B0 \u09AA\u09CD\u09B0\u09AF\u09BC\u09CB\u099C\u09A8 \u09B9\u09AC\u09C7 \u09A8\u09BE\u0964.</li>
    <li>\u09B2\u09C7\u09A8\u09A6\u09C7\u09A8 \u09AB\u09BF - \u09A0\u09BF\u0995 \u0986\u099B\u09C7, \u0986\u09AE\u09B0\u09BE \u09AC\u09C1\u099D\u09BF \u09AF\u09C7 \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09C7\u0995\u09C7\u09B0\u0987 \u0985\u09B0\u09CD\u09A5 \u0989\u09AA\u09BE\u09B0\u09CD\u099C\u09A8 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7 \u098F\u09AC\u0982 \u098F\u099F\u09BF \u09AC\u09BF\u099C\u09CD\u099E\u09BE\u09AA\u09A8 \u0987\u09A4\u09CD\u09AF\u09BE\u09A6\u09BF \u09A6\u09CD\u09AC\u09BE\u09B0\u09BE \u0986\u099A\u09CD\u099B\u09BE\u09A6\u09BF\u09A4 \u09B9\u09AF\u09BC \u09A8\u09BE, \u09AF\u09BE \u09AC\u09CD\u09AF\u09BE\u0995\u0997\u09CD\u09B0\u09BE\u0989\u09A8\u09CD\u09A1\u09C7 \u099A\u09B2\u09C7 \u098F\u09AC\u0982 \u098F\u0995\u099F\u09BF \u09B2\u09C7\u09A8\u09A6\u09C7\u09A8\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u0986\u09B8\u09BE \u09B8\u09CD\u099F\u09CD\u09AF\u09BE\u09A8\u09CD\u09A1\u09BE\u09B0\u09CD\u09A1 \u09AB\u09BF\u0964. \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09AE\u09B0\u09BE \u098F\u099F\u09BE\u0993 \u099C\u09BE\u09A8\u09BF \u09AF\u09C7 \u0995\u09BF\u099B\u09C1 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09CD\u09B2\u09BE\u09AF\u09BC\u09C7\u09A8\u09CD\u099F\u09A6\u09C7\u09B0 \u09AA\u09B0\u09BF\u09B7\u09C7\u09AC\u09BE \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u09A4\u09BE\u09B0\u09BE \u09AF\u09C7 \u09AB\u09BF \u09A8\u09C7\u09AF\u09BC \u09A4\u09BE\u09B0 \u0989\u09AA\u09B0 \u09AD\u09BE\u09B0\u09C0 \u099A\u09BE\u09AA \u09A6\u09BF\u09A4\u09C7 \u099A\u09BE\u09AF\u09BC\u0964. \u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA \u09B9\u09BF\u09B8\u09BE\u09AC\u09C7 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C7\u09A8 \u09A4\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u098F\u0987 \u09B8\u09AE\u09B8\u09CD\u09AF\u09BE\u099F\u09BF \u09AA\u09BE\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964.</li>
  </ul>
  
  <h2>\u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u099C\u09C1\u09AF\u09BC\u09BE\u09B0 \u0985\u09B8\u09C1\u09AC\u09BF\u09A7\u09BE</h2>
  <ul>
    <li>\u0995\u09CB\u09A8\u09CB \u099A\u09BE\u09B0\u09CD\u099C\u09AC\u09CD\u09AF\u09BE\u0995/\u09B0\u09BF\u09AD\u09BE\u09B0\u09CD\u09B8\u09BE\u09B2 \u09A8\u09C7\u0987 - \u09A6\u09C1\u09B0\u09CD\u09AD\u09BE\u0997\u09CD\u09AF\u09AC\u09B6\u09A4, \u098F\u0987 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u099F\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u0986\u09AA\u09A8\u09BE\u09B0 \u0995\u09CB\u09A8\u09CB \u099F\u09C7\u0995 \u09AC\u09CD\u09AF\u09BE\u0995 \u09A8\u09C7\u0987\u0964. \u0986\u09AA\u09A8\u09BE\u09B0 \u0985\u09CD\u09AF\u09BE\u0995\u09BE\u0989\u09A8\u09CD\u099F\u09C7 \u09B2\u09C7\u09A8\u09A6\u09C7\u09A8\u099F\u09BF \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u09AA\u09B0 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BE\u09B0 \u0993\u09AF\u09BC\u09BE\u09B2\u09C7\u099F \u09A5\u09C7\u0995\u09C7 \u098F\u099F\u09BF \u099A\u09B2\u09C7 \u0997\u09C7\u099B\u09C7, \u09A4\u0996\u09A8 \u09B8\u09C7\u099F\u09BF \u09B8\u09AE\u09CD\u09AA\u09A8\u09CD\u09A8 \u09B9\u09AF\u09BC\u09C7 \u0997\u09C7\u099B\u09C7\u0964. \u09A4\u09BE\u0987 \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u09B9\u09AF\u09BC\u09C7 \u09A8\u09BF\u09A8 \u09AF\u09C7 \u0986\u09AA\u09A8\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09AC\u09BE \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0997\u09C7\u09AE\u09BF\u0982 \u09B8\u09BE\u0987\u099F\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u098F\u09AC\u0982 \u099F\u09BE\u0995\u09BE \u09AC\u09CD\u09AF\u09AF\u09BC \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A4\u09BE\u09A6\u09C7\u09B0 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u09AA\u09C2\u09B0\u09CD\u09AC\u09AC\u09B0\u09CD\u09A4\u09C0 \u09A4\u09A5\u09CD\u09AF\u0997\u09C1\u09B2\u09BF \u0985\u09AC\u09B6\u09CD\u09AF\u0987 \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE \u0995\u09B0\u09C7 \u09A8\u09C7\u0993\u09AF\u09BC\u09BE \u0989\u099A\u09BF\u09A4 \u0995\u09C7\u09A8\u09A8\u09BE \u0995\u09CD\u09B0\u09C7\u09A1\u09BF\u099F \u0995\u09BE\u09B0\u09CD\u09A1 \u098F\u09AC\u0982 \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0990\u09A4\u09BF\u09B9\u09BE\u09B8\u09BF\u0995 \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF\u09B0 \u09B8\u09AE\u09BE\u09A8 \u09B8\u09BF\u0995\u09BF\u0989\u09B0\u09BF\u099F\u09BF \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0989\u09AA\u09B2\u09AC\u09CD\u09A7 \u09A8\u09C7\u0987\u0964.</li>
    <li>\u09B2\u09C7\u09A8\u09A6\u09C7\u09A8 \u09B8\u09AE\u09B8\u09CD\u09AF\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AF\u0996\u09A8 \u09B8\u09AE\u09B8\u09CD\u09AF\u09BE\u09B0 \u09AA\u09B0\u09BF\u09B8\u09CD\u09A5\u09BF\u09A4\u09BF \u09A5\u09BE\u0995\u09C7 \u09A4\u0996\u09A8 "\u0997\u09CD\u09B0\u09BE\u09B9\u0995 \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u09B8\u09A0\u09BF\u0995" \u09A8\u09AF\u09BC - \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09BE\u09B8\u09CD\u099F\u09AE\u09BE\u09B0 \u09B8\u09BE\u09B0\u09CD\u09AD\u09BF\u09B8 \u09B8\u09C7\u09B0\u09BE \u09A8\u09BE \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u0995\u09A5\u09BE \u09AC\u09B0\u09CD\u09A3\u09A8\u09BE \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964. \u09A4\u09BE\u09B0\u09BE \u09B8\u09AE\u09B8\u09CD\u09A4 \u0997\u09CD\u09B0\u09BE\u09B9\u0995\u09A6\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AD\u09BE\u09B2 \u09AF\u09CB\u0997\u09BE\u09AF\u09CB\u0997 \u09B0\u0995\u09CD\u09B7\u09BE \u0995\u09B0\u09C7 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09A8\u09BF\u099C\u09C7\u0987 \u09B8\u09AE\u09BE\u09A7\u09BE\u09A8 \u0995\u09B0\u09A4\u09C7 \u09AC\u09BE \u0995\u09BF\u099B\u09C1 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u09AC\u09CB\u099D\u09BE \u09A8\u09BE \u09A6\u09BF\u09AF\u09BC\u09C7 \u099B\u09BE\u09A1\u09BC\u09BE\u09A8\u09CB \u09B9\u09AC\u09C7 \u09A8\u09BE\u0964. \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09AA\u09A8\u09BE\u09B0 \u0985\u09CD\u09AF\u09BE\u0995\u09BE\u0989\u09A8\u09CD\u099F \u09A5\u09C7\u0995\u09C7 \u098F\u0995\u09AC\u09BE\u09B0 \u099F\u09BE\u0995\u09BE \u099A\u09B2\u09C7 \u0997\u09C7\u09B2\u09C7 \u098F\u09B0 \u09AB\u09BF\u09B0\u09C7 \u09AA\u09BE\u0993\u09AF\u09BC\u09BE\u09B0 \u09B8\u09AE\u09CD\u09AD\u09BE\u09AC\u09A8\u09BE \u0996\u09C1\u09AC \u0995\u09AE \u09A5\u09BE\u0995\u09C7 \u09AC\u09BE \u09A8\u09C7\u0987\u0964. \u09A4\u09BE\u0987 \u0986\u09AA\u09A8\u09BE\u09B0 \u098F\u099F\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AF\u0996\u09A8 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u0995\u09A4 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A4\u09BE \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u09AF\u09BE\u09B0 \u0995\u09BE\u099B\u09C7 \u09AA\u09C7\u09AE\u09C7\u09A8\u09CD\u099F \u0995\u09B0\u099B\u09C7\u09A8 \u09A4\u09BE\u0995\u09C7 \u09B8\u09A4\u09CD\u09AF\u09BF\u0995\u09BE\u09B0\u09C7 \u0986\u09AA\u09A8\u09BF \u09AC\u09BF\u09B6\u09CD\u09AC\u09BE\u09B8 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964.</li>
  </ul>
  
  <h2>\u0986\u09AE\u09BF \u0995\u09BF\u09AD\u09BE\u09AC\u09C7 \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09BF \u09AF\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B8\u09BE\u0987\u099F \u09A8\u09BF\u09B0\u09BE\u09AA\u09A6?</h2>
  <p>\u0986\u099C\u0995\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09AC\u09C7\u09B6\u09BF\u09B0\u09AD\u09BE\u0997 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09A8\u09BF\u09B0\u09BE\u09AA\u09A6 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09BE\u099B\u09C7 \u09B8\u09AE\u09AF\u09BC \u0995\u09BE\u099F\u09BE\u09A8\u09CB\u09B0 \u099A\u09BF\u09A8\u09CD\u09A4\u09BE \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7 \u09A8\u09BE\u0964. \u09A4\u09AC\u09C7, \u0995\u09CB\u09A8\u0993 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09C7\u09B0\u09BE \u09B8\u09CD\u09AC\u09BE\u09B0\u09CD\u09A5 \u09A8\u09BF\u09AF\u09BC\u09C7 \u099A\u09BF\u09A8\u09CD\u09A4\u09BE \u0995\u09B0\u09C7 \u09A8\u09BE \u09A4\u09BE \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964. \u098F\u0987 \u0995\u09BE\u09B0\u09A3\u09C7 \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AC\u09CD\u09AF\u09BE\u0995\u0997\u09CD\u09B0\u09BE\u0989\u09A8\u09CD\u09A1 \u099A\u09C7\u0995 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7, \u098F\u09AE\u09A8\u0995\u09BF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0997\u09C7\u09AE\u09AC\u09CD\u09B2\u09BF\u0982 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u0995\u09A5\u09BE \u0986\u09B8\u09B2\u09C7, \u09AC\u09BE \u09AC\u09B2\u09BE \u0989\u099A\u09BF\u09A4 \u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C7 \u099C\u09C1\u09AF\u09BC\u09BE \u0996\u09C7\u09B2\u09A4\u09C7 \u099A\u09BE\u09A8\u0964. \u098F\u0996\u09BE\u09A8\u09C7 \u0995\u09CB\u09A8\u0993 \u0985\u09A4\u09BF\u09B0\u09BF\u0995\u09CD\u09A4 \u09A8\u09BF\u09B0\u09BE\u09AA\u09A4\u09CD\u09A4\u09BE \u09A8\u09C7\u0987 \u098F\u09AC\u0982 \u09AF\u0996\u09A8 \u0985\u09B0\u09CD\u09A5 \u0986\u09AA\u09A8\u09BE\u09B0 \u0993\u09AF\u09BC\u09BE\u09B2\u09C7\u099F \u09A5\u09C7\u0995\u09C7 \u099A\u09B2\u09C7 \u09AF\u09BE\u09AF\u09BC, \u0986\u09AA\u09A8\u09BE\u09B0 \u0985\u09B0\u09CD\u09A5 \u09AB\u09C7\u09B0\u09A4 \u09AA\u09BE\u0993\u09AF\u09BC\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0985\u09A8\u09C7\u0995 \u09B8\u09C1\u09AF\u09CB\u0997 \u09A8\u09C7\u0987\u0964.</p>
  <p>\u09AD\u09BE\u0997\u09CD\u09AF\u09AC\u09BE\u09A8\u09AD\u09BE\u09AC\u09C7, \u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u0995\u09BE\u099F\u09BE\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A4\u09AC\u09C7 \u0986\u09B8\u09B2\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u099F\u09BF \u0986\u09AA\u09A8\u09BF \u0995\u09BF \u09B8\u09A4\u09CD\u09AF\u0987 \u09AC\u09BF\u09B6\u09CD\u09AC\u09BE\u09B8 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09AC\u09C7\u09A8 \u09A4\u09BE \u099C\u09BE\u09A8\u09A4\u09C7 \u0995\u09BF\u099B\u09C1 \u0989\u09AA\u09BE\u09AF\u09BC \u0986\u099B\u09C7\u0964. \u09B8\u09C7\u09B0\u09BE \u0989\u09AA\u09BE\u09AF\u09BC \u09B9\u09B2 \u099A\u09C7\u0995 \u0995\u09B0\u09BE \u09AF\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u099F\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0997\u09C7\u09AE\u09AC\u09CD\u09B2\u09BF\u0982 \u098F\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09C8\u09A7 \u09B2\u09BE\u0987\u09B8\u09C7\u09A8\u09CD\u09B8 \u0986\u099B\u09C7 \u0995\u09BF \u09A8\u09BE\u0964. \u09B8\u09AE\u09B8\u09CD\u09A4 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09B0 \u0995\u09BE\u099B\u09C7 \u098F\u099F\u09BF \u0986\u0987\u09A8\u0997\u09A4\u09AD\u09BE\u09AC\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u099A\u09BE\u09B2\u09BE\u09A8\u09CB\u09B0 \u099C\u09A8\u09CD\u09AF \u09AA\u09CD\u09B0\u09AF\u09BC\u09CB\u099C\u09A8 \u098F\u09AC\u0982 \u098F\u099F\u09BF \u09AC\u09BF\u09A8\u09BE\u09AE\u09C2\u09B2\u09CD\u09AF\u09C7 \u09A8\u09AF\u09BC, \u09A4\u09BE\u0987 \u098F\u099F\u09BF \u0995\u09BF\u099B\u09C1 \u09AF\u09BE \u09A4\u09BE\u09A6\u09C7\u09B0 \u09B2\u09C1\u0995\u09BF\u09AF\u09BC\u09C7 \u09B0\u09BE\u0996\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7 \u09A8\u09BE\u0964. \u0995\u09BF\u099B\u09C1 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u098F\u0995\u09BE\u09A7\u09BF\u0995 \u09B2\u09BE\u0987\u09B8\u09C7\u09A8\u09CD\u09B8 \u0985\u09B0\u09CD\u099C\u09A8 \u0995\u09B0\u09BE\u09B0 \u09B8\u09BF\u09A6\u09CD\u09A7\u09BE\u09A8\u09CD\u09A4 \u09A8\u09C7\u0993\u09AF\u09BC\u09BE \u09B9\u09AF\u09BC\u0964. \u098F\u099F\u09BF \u0995\u09DF\u09C7\u0995\u099C\u09A8\u0995\u09C7 \u098F\u0995\u099F\u09BF \u09B2\u09BE\u09B2 \u09AA\u09A4\u09BE\u0995\u09BE \u09B9\u09BF\u09B8\u09BE\u09AC\u09C7 \u09A7\u09BE\u09B0\u09A3 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09AE\u09B0\u09BE \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AC\u09B2\u09A4\u09C7 \u098F\u0996\u09BE\u09A8\u09C7 \u098F\u099F\u09BF \u098F\u0995\u099F\u09BF \u09B2\u09BE\u09B2 \u09AA\u09A4\u09BE\u0995\u09BE \u09A8\u09AF\u09BC\u0964. \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u09A4\u09BE\u09B0\u09BE \u09AF\u09A4\u099F\u09BE \u0987\u099A\u09CD\u099B\u09BE \u0995\u09B0\u09C7 \u09B2\u09BE\u0987\u09B8\u09C7\u09A8\u09CD\u09B8 \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09A4\u09BE\u09B0\u09BE \u098F\u0995\u099F\u09BF \u09B2\u09BE\u0987\u09B8\u09C7\u09A8\u09CD\u09B8 \u09A5\u09BE\u0995\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7 \u098F\u09AC\u0982 \u098F\u099F\u09BF \u09B8\u09AE\u09CD\u09AD\u09AC\u0964.</p>
  <p>\u09B8\u09BE\u09A5\u09C7 \u09B8\u09BE\u09A5\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u099F\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09A6\u09C7\u0996\u09BE \u098F\u0995\u099F\u09BF \u09AD\u09BE\u09B2 \u09A7\u09BE\u09B0\u09A3\u09BE \u09B9\u09AF\u09BC\u0964 \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0997\u09C7\u09AE\u09BE\u09B0\u09A6\u09C7\u09B0 \u0995\u09BF \u09AC\u09B2\u09BE \u09B9\u099A\u09CD\u099B\u09C7 \u09A4\u09BE \u09A6\u09C7\u0996\u09A4\u09C7 \u09B8\u09B0\u09CD\u09AC\u09A6\u09BE \u09AD\u09BE\u09B2 \u0989\u09AA\u09BE\u09AF\u09BC\u0964. \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09AF\u09A6\u09BF \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF\u09A6\u09C7\u09B0 \u09B8\u0999\u09CD\u0997\u09C7 \u0985\u09AC\u09BF\u09A8\u09AF\u09BC\u09C0 \u09B9\u09AF\u09BC, \u09A4\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u09A4\u09BE\u09A6\u09C7\u09B0 \u09AA\u09CD\u09B0\u09A5\u09AE \u098F\u0995\u099C\u09A8 \u09A8\u09AF\u09BC - \u09B8\u09C7\u0987 \u0995\u09CD\u09B7\u09A3 \u09B8\u09AE\u09CD\u09AD\u09AC\u09A4\u0983 \u098F\u0995\u099F\u09BF \u09B0\u09BF\u09AD\u09BF\u0989 \u09A5\u09BE\u0995\u09AC\u09C7 \u09AF\u09BE \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AC\u09B2\u09AC\u09C7 \u098F\u099F\u09BF \u0995\u09C0\u09AD\u09BE\u09AC\u09C7 \u0998\u099F\u09C7\u099B\u09BF\u09B2 \u098F\u09AC\u0982 \u0995\u09C0 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964. \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09C7\u09B0\u09BE \u09AC\u09BF\u09AC\u09C7\u099A\u09A8\u09BE \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C1\u09A8 \u098F\u09AC\u0982 \u09AF\u09A6\u09BF \u0995\u09CB\u09A8\u0993 \u099C\u09C1\u09A1\u09BC\u09BE\u09A4\u09A8 \u09B8\u09BE\u0987\u099F\u09C7\u09B0 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u0995\u09BF\u099B\u09C1 \u0985\u09A8\u09C1\u09AD\u09AC \u09B9\u09AF\u09BC, \u09A4\u09AC\u09C7 \u09AC\u09B9\u09C1\u09A4 \u0986\u09B0\u0993 \u09B8\u09BE\u0987\u099F \u09B0\u09AF\u09BC\u09C7\u099B\u09C7\u0964. \u098F\u0995\u099F\u09BF \u09AA\u09C3\u09A5\u0995 \u09B8\u09BE\u0987\u099F \u099A\u09AF\u09BC\u09A8 \u0995\u09B0\u09C1\u09A8 \u098F\u09AC\u0982 \u09AC\u09BF\u09B6\u09CD\u09AC\u09BE\u09B8\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u099C\u09C1\u09A1\u09BC\u09BE\u09A4\u09A8 \u0995\u09B0\u09BE\u09B0 \u0995\u09CB\u09A8\u0993 \u09AA\u09CD\u09B0\u09AF\u09BC\u09CB\u099C\u09A8 \u09A8\u09C7\u0987\u0964.</p>

  <h2>\u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB\u09A4\u09C7 \u099C\u09AE\u09BE \u0995\u09B0\u09C7\u09A8 \u09A4\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u0995\u09BF \u098F\u0996\u09A8\u0993 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09AA\u09BE\u09AC\u09C7\u09A8?</h2>
  <p>\u0986\u09AE\u09B0\u09BE \u09AC\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09BF \u09AF\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0985\u09AD\u09BF\u099C\u09CD\u099E\u09A4\u09BE, \u0989\u09A4\u09CD\u09A4\u09C7\u099C\u09A8\u09BE, \u09AE\u099C\u09BE \u098F\u09AC\u0982 \u0996\u09C7\u09B2\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AA\u09CD\u09B0\u09A4\u09BF\u09B7\u09CD\u09A0\u09BE\u09A8\u0997\u09C1\u09B2\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09BE\u0993\u09AF\u09BC\u09BE \u0997\u09C7\u09B2\u09C7 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09A6\u09C7\u09B0 \u0986\u0995\u09B0\u09CD\u09B7\u09A3 \u0995\u09B0\u09C7 \u09A4\u09BE\u09A6\u09C7\u09B0 \u09AA\u0995\u09CD\u09B7\u09C7 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09B8\u09B2\u09C7 \u098F\u099F\u09BE \u09AE\u09BF\u09A5\u09CD\u09AF\u09BE \u09B9\u09AC\u09C7 \u09AC\u09B2\u09C7 \u0995\u09C7\u0989 \u09A8\u09BE \u0995\u09C7\u09A8\u0964. \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09B0\u09BE \u09AC\u09A1\u09BC \u099C\u09AF\u09BC\u09C7\u09B0 \u09AA\u09A5\u09C7 \u09A4\u09BE\u09A6\u09C7\u09B0 \u09B8\u09BE\u09B9\u09BE\u09AF\u09CD\u09AF \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09CB\u09A8\u09BE\u09B8 \u098F\u09AC\u0982 \u09AA\u09CD\u09B0\u099A\u09C1\u09B0 \u09AC\u09CB\u09A8\u09BE\u09B8 \u099A\u09BE\u09AF\u09BC\u0964. \u09AC\u09CB\u09A8\u09BE\u09B8\u0997\u09C1\u09B2\u09BF \u0995\u09C7\u09AC\u09B2 \u09AE\u09C1\u09B2\u09CD\u09AF\u09AC\u09BE\u09A8 \u099F\u09BE\u0995\u09BE \u09AF\u09C7\u09AE\u09A8, \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u098F\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AF\u09C7 \u09B6\u09B0\u09CD\u09A4\u09BE\u09A6\u09BF \u0986\u099B\u09C7 \u09A4\u09BE \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09BE\u09B0 \u0986\u0997\u09C7 \u09A6\u09C7\u0996\u09C1\u09A8\u0964.</p>
  <p>\u09A7\u09B0\u09C1\u09A8 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB\u09A4\u09C7 \u099C\u09AE\u09BE \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964. \u09B8\u09C7\u0987 \u0995\u09CD\u09B7\u09C7\u09A4\u09CD\u09B0\u09C7, \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0\u0995\u09BE\u09B0\u09C0\u09B0 \u0985\u09AD\u09BF\u099C\u09CD\u099E\u09A4\u09BE \u0986\u09AE\u09BE\u09A6\u09C7\u09B0 \u09AC\u09B2\u09C7 \u09AF\u09C7 \u09AC\u09CB\u09A8\u09BE\u09B8\u0997\u09C1\u09B2\u09BF \u099B\u09CB\u099F \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09AA\u09A8\u09BF \u09AF\u09BE \u09AA\u09BE\u09A8 \u09A4\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0996\u09BE\u09B0\u09BE\u09AA \u09A8\u09AF\u09BC\u0964. \u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u09AA\u09CD\u09B0\u09A5\u09AE\u09AC\u09BE\u09B0\u09C7\u09B0 \u09AE\u09A4\u09CB \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC \u09B9\u09A8 \u09A4\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u098F\u0995\u099F\u09BF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u098F\u0995\u099F\u09BF \u09B8\u09CD\u09AC\u09BE\u0997\u09A4 \u09AA\u09CD\u09AF\u09BE\u0995\u09C7\u099C \u09AA\u09BE\u09AC\u09C7\u09A8\u0964. \u098F\u099F\u09BF \u09B8\u09C7\u0987 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09AF\u09BE \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AF\u09BE\u09A4\u09CD\u09B0\u09BE \u09B6\u09C1\u09B0\u09C1 \u0995\u09B0\u09AC\u09C7 \u098F\u09AC\u0982 \u098F\u099F\u09BF \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AC\u09A1\u09BC \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F\u09C7 \u09AF\u09C7\u09A4\u09C7 \u09B8\u09BE\u09B9\u09BE\u09AF\u09CD\u09AF \u0995\u09B0\u09AC\u09C7\u0964.</p>
  <p>\u098F\u099F\u09BF \u09B6\u09C1\u09A7\u09C1\u09AE\u09BE\u09A4\u09CD\u09B0 \u09B8\u09CD\u09AC\u09BE\u0997\u09A4 \u09AC\u09CB\u09A8\u09BE\u09B8 \u0989\u09AA\u09B2\u09AC\u09CD\u09A7 \u09A8\u09AF\u09BC\u0964. \u0993\u09AF\u09BC\u09C7\u09B2\u0995\u09BE\u09AE \u09AC\u09CB\u09A8\u09BE\u09B8 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u09AA\u09B0\u09C7, \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u09AC\u09CB\u09A8\u09BE\u09B8\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09AA\u09A8\u09BE\u09B0 \u099A\u09CB\u0996 \u09AC\u09A8\u09CD\u09A7 \u09B0\u09BE\u0996\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964. \u098F\u099F\u09BF\u0987 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09AF\u09BE \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0995\u0996\u09A8\u0993 \u0995\u0996\u09A8\u0993 \u0986\u09AA\u09A8\u09BE\u09B0 \u0996\u09C7\u09B2\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09C7\u099F \u0995\u09B0\u09BE \u09B0\u09CD\u09AF\u09BE\u09A8\u09CD\u09A1\u09AE \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F\u09C7\u09B0 \u0989\u09AA\u09B0 \u09A6\u09C7\u09AF\u09BC\u0964. \u098F\u09AC\u0982 \u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u09AD\u09BE\u0997\u09CD\u09AF\u09AC\u09BE\u09A8 \u09B9\u09A8 \u09A4\u09AC\u09C7 \u098F\u099F\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AC\u09A1\u09BC \u09AC\u09BE \u099B\u09CB\u099F \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F \u09A8\u09BF\u09AF\u09BC\u09C7 \u0986\u09B8\u09AC\u09C7\u0964.</p>
  <p>\u09A0\u09BF\u0995 \u09AF\u09C7\u09AE\u09A8 \u0986\u09AA\u09A8\u09BF \u09AF\u0996\u09A8 \u098F\u0995\u099F\u09BF \u09B8\u09CD\u099F\u09CD\u09AF\u09BE\u09A8\u09CD\u09A1\u09BE\u09B0\u09CD\u09A1 \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u09B8\u09C7\u099F \u0995\u09B0\u09C7\u09A8, \u0986\u09AA\u09A8\u09BF \u09AF\u0996\u09A8 \u098F\u0995\u099F\u09BF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u09B0\u09BE\u0996\u09C7\u09A8 \u09A4\u0996\u09A8 \u0986\u09AA\u09A8\u09BF \u0995\u09CD\u09AF\u09BE\u09B6\u09BF\u09AF\u09BC\u09BE\u09B0\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09A6\u09BE\u09AC\u09BF \u0995\u09B0\u09C7\u09A8\u0964. \u098F\u09AC\u0982 \u09AE\u09A8\u09C7 \u09B0\u09BE\u0996\u09AC\u09C7\u09A8 \u09AF\u09C7 \u0995\u09C7\u0989 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09B8\u09C7\u0987 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09A8\u09BF\u09A4\u09C7 \u09AC\u09BE\u09A7\u09CD\u09AF \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09AC\u09C7 \u09A8\u09BE\u0964. \u09B8\u09BF\u09A6\u09CD\u09A7\u09BE\u09A8\u09CD\u09A4 \u0986\u09AA\u09A8\u09BE\u09B0. \u09AC\u09CB\u09A8\u09BE\u09B8\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u0986\u09B8\u09BE \u09B8\u09AE\u09B8\u09CD\u09A4 \u09A8\u09BF\u09AF\u09BC\u09AE \u0993 \u09B6\u09B0\u09CD\u09A4\u09BE\u09AC\u09B2\u09C0 \u09A6\u09C7\u0996\u09BE\u09B0 \u09AA\u09B0 \u098F\u099F\u09BF \u098F\u0995\u099F\u09BF \u09AA\u099B\u09A8\u09CD\u09A6 \u09AF\u09BE \u0986\u09AA\u09A8\u09BE\u09B0 \u0995\u09B0\u09BE \u0989\u099A\u09BF\u09A4\u0964. \u09AE\u09A8\u09C7 \u09B0\u09BE\u0996\u09AC\u09C7\u09A8, \u0986\u09AA\u09A8\u09BF \u09AF\u09C7 \u099C\u09AF\u09BC\u09B2\u09BE\u09AD\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09AF\u09A5\u09C7\u09B7\u09CD\u099F \u09AD\u09BE\u0997\u09CD\u09AF\u09AC\u09BE\u09A8 \u09A4\u09BE \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09BE\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u0986\u0997\u09C7 \u09AC\u09BE\u099C\u09BF\u09B0 \u09AA\u09CD\u09B0\u09AF\u09BC\u09CB\u099C\u09A8\u09C0\u09AF\u09BC\u09A4\u09BE \u0985\u09AC\u09B6\u09CD\u09AF\u0987 \u09AA\u09C2\u09B0\u09A3 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964. \u098F\u099B\u09BE\u09A1\u09BC\u09BE\u0993, \u09AE\u09A8\u09C7 \u09B0\u09BE\u0996\u09AC\u09C7\u09A8 \u09AF\u09C7 \u09AA\u09CD\u09B0\u099A\u09C1\u09B0 \u0985\u09B0\u09CD\u09A5 \u099C\u09C7\u09A4\u09BE\u09B0 \u09B8\u09C1\u09AF\u09CB\u0997 \u09A5\u09BE\u0995\u09B2\u09C7\u0993, \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AE\u09A8\u09C7 \u09B0\u09BE\u0996\u09A4\u09C7 \u09B9\u09AC\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B6\u09C1\u09A7\u09C1\u09AE\u09BE\u09A4\u09CD\u09B0 \u09AC\u09BF\u09A8\u09CB\u09A6\u09A8\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF\u0964.</p>
  
  <h2>\u0995\u09BF\u09AD\u09BE\u09AC\u09C7 \u09B8\u09A0\u09BF\u0995 \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09A8\u09BF\u09B0\u09CD\u09AC\u09BE\u099A\u09A8 \u0995\u09B0\u09AC\u09C7\u09A8</h2>
  <p>\u0986\u09AE\u09B0\u09BE \u09B8\u09AC\u09BE\u0987 \u098F\u0996\u09A8\u0987 \u09B8\u09C7\u09B0\u09BE \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u099F\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u099A\u09BE\u0987, \u0986\u09AE\u09B0\u09BE \u09AA\u09CD\u09B0\u09A5\u09AE \u09B8\u09CD\u09AA\u09BF\u09A8\u09C7 \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F\u0995\u09C7 \u0986\u0998\u09BE\u09A4 \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u0987, \u0986\u09AE\u09B0\u09BE \u09B8\u09AC\u09BE\u0987 \u098F\u099F\u09BF \u09AA\u09C7\u09A4\u09C7 \u099A\u09BE\u0987, \u098F\u09AC\u0982 \u0986\u09AE\u09B0\u09BE \u09B8\u09B0\u09BE\u09B8\u09B0\u09BF \u098F\u099F\u09BF \u099A\u09BE\u0987\u0964. \u09A6\u09C1\u09B0\u09CD\u09AD\u09BE\u0997\u09CD\u09AF\u0995\u09CD\u09B0\u09AE\u09C7, \u098F\u099F\u09BF \u09AC\u09BE\u09B8\u09CD\u09A4\u09AC\u09A4\u09BE \u09A8\u09AF\u09BC\u0964. \u0986\u09AE\u09B0\u09BE \u09B6\u09BF\u0996\u09BF.</p>
  <p>\u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u098F\u09B8\u09C7\u0993 \u09AC\u09CD\u09AF\u09BE\u09AA\u0995 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8 \u098F\u09AC\u0982 \u09AA\u09CD\u09B0\u09A5\u09AE \u09B8\u09CD\u09AA\u09BF\u09A8\u09C7 \u09A8\u09BF\u0996\u09C1\u0981\u09A4 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09B0 \u099C\u09A8\u09CD\u09AF \u0995\u09CB\u09A8\u09CB \u0997\u09CB\u09AA\u09A8 \u09B0\u09CB\u09A1 \u09AE\u09CD\u09AF\u09BE\u09AA \u09A8\u09C7\u0987 - \u09A4\u09AC\u09C7 \u098F\u0996\u09BE\u09A8\u09C7 \u0995\u09AF\u09BC\u09C7\u0995\u099F\u09BF \u099F\u09BF\u09AA\u09B8 \u09B0\u09AF\u09BC\u09C7\u099B\u09C7:</p>
  <ul>
    <li>\u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09A6\u09C7\u0996\u09A4\u09C7 \u09B9\u09AC\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0995\u09CB\u09A8 \u09A7\u09B0\u09A8\u09C7\u09B0 \u0997\u09C7\u09AE \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09C7 \u09AF\u09A6\u09BF \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09BE\u099B\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u099B\u09A8\u09CD\u09A6\u09C7\u09B0 \u0995\u09CB\u09A8\u09CB \u0997\u09C7\u09AE \u09A8\u09BE \u09A5\u09BE\u0995\u09C7 \u09AC\u09BE \u0986\u09AA\u09A8\u09BF \u099A\u09C7\u09B7\u09CD\u099F\u09BE \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u09A8 \u098F\u09AE\u09A8 \u0995\u09CB\u09A8\u09CB \u0997\u09C7\u09AE \u09A8\u09BE \u09A5\u09BE\u0995\u09C7\u0964.</li>
    <li>\u09A7\u09B0\u09C1\u09A8 \u0986\u09AA\u09A8\u09BE\u09B0 \u0995\u09BE\u099B\u09C7 \u098F\u0995 \u09A7\u09B0\u09A8\u09C7\u09B0 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB\u0995\u09BE\u09B0\u09C7\u09A8\u09CD\u09B8\u09BF \u0986\u099B\u09C7 \u098F\u09AC\u0982 \u09B8\u09C7\u0997\u09C1\u09B2\u09BF \u09B8\u09AC \u09A8\u09AF\u09BC \u09AC\u09BE \u0986\u09AA\u09A8\u09BF \u09AF\u09BE \u099C\u09BE\u09A8\u09C7\u09A8 \u09A4\u09BE\u09B0 \u09A5\u09C7\u0995\u09C7 \u0986\u09B2\u09BE\u09A6\u09BE \u098F\u0995\u099F\u09BF \u099A\u09C7\u09B7\u09CD\u099F\u09BE \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A8\u09BE\u09F7. \u09B8\u09C7\u0995\u09CD\u09B7\u09C7\u09A4\u09CD\u09B0\u09C7, \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF \u09B9\u09BF\u09B8\u09BE\u09AC\u09C7 \u098F\u0987 \u09AA\u09CD\u09B0\u0995\u09BE\u09B0\u099F\u09BF \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09C7 \u09A4\u09BE \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u0995\u09B0\u09A4\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF\u0997\u09C1\u09B2\u09BF \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964.</li>
    <li>\u09AC\u09CB\u09A8\u09BE\u09B8 - \u0986\u09AE\u09B0\u09BE \u099C\u09BE\u09A8\u09BF \u0986\u09AE\u09B0\u09BE \u0987\u09A4\u09BF\u09AE\u09A7\u09CD\u09AF\u09C7 \u0997\u09C1\u09B0\u09C1\u09A4\u09CD\u09AC\u09AA\u09C2\u09B0\u09CD\u09A3 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u0995\u09A5\u09BE \u09AC\u09B2\u09C7\u099B\u09BF, \u09A4\u09AC\u09C7 \u0986\u09AE\u09B0\u09BE \u098F\u099F\u09BF \u09AA\u09C1\u09A8\u09B0\u09BE\u09AC\u09C3\u09A4\u09CD\u09A4\u09BF \u0995\u09B0\u09AC\u0964. \u0986\u09AE\u09B0\u09BE \u099C\u09BE\u09A8\u09BF \u09AF\u09C7 \u0985\u09A8\u09C7\u0995 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC \u0995\u09C7\u09AC\u09B2 \u09A4\u09BE\u09A6\u09C7\u09B0 \u09A8\u09A4\u09C1\u09A8 \u098F\u09AC\u0982 \u09AA\u09C1\u09B0\u09BE\u09A8\u09CB \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09A6\u09C7\u09B0 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0995\u09C0 \u09A7\u09B0\u09A8\u09C7\u09B0 \u09AC\u09CB\u09A8\u09BE\u09B8 \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09AC\u09C7 \u09B8\u09C7\u09A6\u09BF\u0995\u09C7 \u09AE\u09A8\u09CB\u09AF\u09CB\u0997 \u09A6\u09BF\u099A\u09CD\u099B\u09C7\u0964.</li>
    <li>\u0986\u09AA\u09A8\u09BF \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09A4\u09BE \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u0995\u09B0\u09C1\u09A8 - \u09AC\u09C7\u09B6\u09BF\u09B0\u09AD\u09BE\u0997 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u09B8\u09C0\u09AE\u09BE\u09AC\u09A6\u09CD\u09A7 \u09A6\u09C7\u09B6\u0997\u09C1\u09B2\u09BF\u09B0 \u098F\u0995\u099F\u09BF \u09A4\u09BE\u09B2\u09BF\u0995\u09BE \u09B0\u09AF\u09BC\u09C7\u099B\u09C7 \u09AF\u09C7\u0997\u09C1\u09B2\u09BF \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7 \u09A8\u09BE\u0964. \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u0995\u09B0\u09C1\u09A8 \u09AF\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09A6\u09C7\u09B6 \u09B8\u09C0\u09AE\u09BE\u09AC\u09A6\u09CD\u09A7 \u09A4\u09BE\u09B2\u09BF\u0995\u09BE\u09AF\u09BC \u09A8\u09C7\u0987\u0964.</li>
  </ul>
  
  <h2>\u099C\u09AE\u09BE \u0995\u09B0\u09BE \u09AC\u09BE \u0989\u09A4\u09CD\u09A4\u09CB\u09B2\u09A8 \u0995\u09B0\u09BE \u0995\u09BF \u0995\u09A0\u09BF\u09A8?</h2>
  <p>\u0985\u09A8\u09C7\u0995 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF \u09AC\u09CB\u099D\u09BE \u0995\u09A0\u09BF\u09A8, \u098F\u09AC\u0982 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09B0 \u09AC\u09BF\u0995\u09CD\u09B0\u09AF\u09BC \u09AC\u09BF\u09A8\u09CD\u09A6\u09C1 \u09B9\u09B2 \u09AF\u09C7 \u098F\u099F\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u09B8\u09AC\u0995\u09BF\u099B\u09C1 \u0986\u09B0\u0993 \u09B8\u09B9\u099C\u09B2\u09AD\u09CD\u09AF \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u0995\u09A5\u09BE \u2013 \u09A4\u09BE\u0987 \u098F\u099F\u09BF \u0995\u09BF \u09B8\u09B9\u099C?</p>
  <p>\u09B9\u09CD\u09AF\u09BE\u0981, \u098F\u099F\u09BE \u098F\u0995\u099F\u09BE \u09AC\u09BE\u099A\u09CD\u099A\u09BE\u09B0 \u0995\u09BE\u099B \u09A5\u09C7\u0995\u09C7 \u0995\u09CD\u09AF\u09BE\u09A8\u09CD\u09A1\u09BF \u099A\u09C1\u09B0\u09BF \u0995\u09B0\u09BE\u09B0 \u09AE\u09A4\u09CB\u0987 \u09B8\u09B9\u099C\u0964. \u098F\u0995\u099F\u09BF \u0986\u09AE\u09BE\u09A8\u09A4 \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09AE\u09BE\u09A4\u09CD\u09B0 \u0995\u09AF\u09BC\u09C7\u0995\u099F\u09BF \u09A7\u09BE\u09AA \u098F\u09AC\u0982 \u098F\u0995\u099F\u09BF \u09A4\u09CB\u09B2\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09AE\u09BE\u09A4\u09CD\u09B0 \u0995\u09AF\u09BC\u09C7\u0995\u099F\u09BF \u09A7\u09BE\u09AA \u09B0\u09AF\u09BC\u09C7\u099B\u09C7\u09F7. \u098F\u09AC\u0982 \u0985\u09AC\u09B6\u09CD\u09AF\u0987, \u0986\u09AE\u09B0\u09BE \u098F\u0996\u09BE\u09A8\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AC\u09B2\u09A4\u09C7 \u098F\u09B8\u09C7\u099B\u09BF \u09AF\u09C7 \u0995\u09C0\u09AD\u09BE\u09AC\u09C7 \u098F\u099F\u09BF \u0995\u09B0\u09A4\u09C7 \u09B9\u09AF\u09BC:</p>
  <p>\u098F\u0987\u09AD\u09BE\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09AC\u09BE \u0985\u09A8\u09CD\u09AF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09C7 \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u0995\u09B0\u09AC\u09C7\u09A8:</p>
  <ul>
    <li>\u09AA\u09CD\u09B0\u09A5\u09AE\u09A4, \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09CD\u09B0\u09BF\u09AF\u09BC \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C1\u0981\u099C\u09C7 \u09AC\u09C7\u09B0 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7 \u09AF\u09BE \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB\u0995\u09C7 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA \u09B9\u09BF\u09B8\u09BE\u09AC\u09C7 \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09C7 \u098F\u09AC\u0982 \u0995\u09CD\u09AF\u09BE\u09B6\u09BF\u09AF\u09BC\u09BE\u09B0\u09C7\u09B0 \u0995\u09BE\u099B\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AA\u09A5 \u09A4\u09C8\u09B0\u09BF \u0995\u09B0\u09C7\u0964.</li>
    <li>\u0986\u09AA\u09A8\u09BF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09AC\u09BE \u09AD\u09BF\u09A8\u09CD\u09A8 \u09A7\u09B0\u09A8\u09C7\u09B0 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u0987\u09B2\u09C7 \u09AC\u09C7\u099B\u09C7 \u09A8\u09BF\u09A8\u0964.</li>
    <li>\u098F\u09AC\u0982 \u09A4\u09BE\u09B0\u09AA\u09B0 \u09AF\u09BE \u09AC\u09BE\u0995\u09BF \u0986\u099B\u09C7 \u09A4\u09BE \u09B9\u09B2 \u0986\u09AA\u09A8\u09BF \u0995\u09A4\u099F\u09BE \u099C\u09AE\u09BE \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A4\u09BE \u099F\u09BE\u0987\u09AA \u0995\u09B0\u09C1\u09A8 \u098F\u09AC\u0982 \u098F\u09A8\u09CD\u099F\u09BE\u09B0 \u0995\u09CD\u09B2\u09BF\u0995 \u0995\u09B0\u09C1\u09A8\u0964. \u098F\u09AC\u0982 \u09A4\u09BE\u09B0\u09AA\u09B0\u09C7 \u09AF\u09BE \u09AC\u09BE\u0995\u09BF \u0986\u099B\u09C7 \u09A4\u09BE \u09B9\u09B2 \u0986\u09AA\u09A8\u09BF \u0995\u09A4\u099F\u09BE \u099C\u09AE\u09BE \u0995\u09B0\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A4\u09BE \u099F\u09BE\u0987\u09AA \u0995\u09B0\u09C1\u09A8 \u098F\u09AC\u0982 \u098F\u09A8\u09CD\u099F\u09BE\u09B0 \u0995\u09CD\u09B2\u09BF\u0995 \u0995\u09B0\u09C1\u09A8\u0964.</li>
  </ul>
  <p>\u098F\u0987\u09AD\u09BE\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09BE\u09B9\u09BE\u09B0 \u0995\u09B0\u09AC\u09C7\u09A8 \u09AF\u09A6\u09BF \u098F\u09AC\u0982 \u09AF\u0996\u09A8 \u0986\u09AA\u09A8\u09BF \u099C\u09BF\u09A4\u09A4\u09C7 \u09AF\u09A5\u09C7\u09B7\u09CD\u099F \u09AD\u09BE\u0997\u09CD\u09AF\u09AC\u09BE\u09A8 \u09B9\u09A8:</p>
  <ul>
    <li>\u09AA\u09CD\u09B0\u09A5\u09AE\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AF\u09BE \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7 \u09A4\u09BE \u09B9\u09B2 \u0995\u09CD\u09AF\u09BE\u09B6\u09BF\u09AF\u09BC\u09BE\u09B0\u09C7\u09B0 \u0995\u09BE\u099B\u09C7 \u09AF\u09C7\u09A4\u09C7 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u09AF\u09C7 \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF\u099F\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AA\u099B\u09A8\u09CD\u09A6 \u0995\u09B0\u09C7\u09A8 \u09B8\u09C7\u099F\u09BF \u09AC\u09C7\u099B\u09C7 \u09A8\u09C7\u0993\u09AF\u09BC\u09BE\u0964</li>
    <li>\u0986\u09AA\u09A8\u09BF \u09AF\u09C7 \u09AA\u09B0\u09BF\u09AE\u09BE\u09A3 \u099F\u09BE\u0995\u09BE \u09A4\u09C1\u09B2\u09A4\u09C7 \u099A\u09BE\u09A8 \u09A4\u09BE \u09AA\u09C2\u09B0\u09A3 \u0995\u09B0\u09C1\u09A8 \u098F\u09AC\u0982 \u09A4\u09BE\u09B0\u09AA\u09B0 \u09A8\u09BF\u09B6\u09CD\u099A\u09BF\u09A4 \u0995\u09B0\u09C1\u09A8 \u099F\u09BF\u09AA\u09C1\u09A8</li>
  </ul>
  <p>\u0986\u09AA\u09A8\u09BF \u09A6\u09C7\u0996\u09A4\u09C7 \u09AA\u09BE\u099A\u09CD\u099B\u09C7\u09A8, \u098F\u099F\u09BF \u098F\u0995\u099F\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0986\u09AA\u09A8\u09BF \u09AF\u09C7 \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AC\u09BF\u0995\u09B2\u09CD\u09AA\u0997\u09C1\u09B2\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09BE\u09A8 \u09A4\u09BE\u09B0 \u099A\u09C7\u09AF\u09BC\u09C7 \u098F\u099F\u09BF \u0985\u09A8\u09C7\u0995 \u09B8\u09B9\u099C \u2013 \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09AE\u09B0\u09BE \u09B8\u09AC\u09BE\u0987 \u099C\u09BE\u09A8\u09BF, \u098F\u099F\u09BF \u098F\u09AE\u09A8 \u0995\u09BF\u099B\u09C1 \u09A8\u09AF\u09BC \u09AF\u09BE \u0986\u09AE\u09B0\u09BE \u09B8\u09B0\u09CD\u09AC\u09A4\u09CD\u09B0 \u09A6\u09C7\u0996\u09A4\u09C7 \u09AA\u09BE\u0987\u0964.</p>

  <h2>\u098F\u0995\u099F\u09BF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0986\u09AA\u09A8\u09BF \u0995\u09CB\u09A8 \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8?</h2>
  <p>\u098F\u0995\u099F\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u099C\u09C1\u09AF\u09BC\u09BE \u09B8\u09BE\u0987\u099F\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09B8\u09B0\u09CD\u09AC\u09CB\u09A4\u09CD\u09A4\u09AE \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0\u0995\u09BE\u09B0\u09C0\u09B0 \u0985\u09AD\u09BF\u099C\u09CD\u099E\u09A4\u09BE \u09AF\u09BE \u09A4\u09C8\u09B0\u09BF \u0995\u09B0\u09C7 \u09A4\u09BE \u09B9\u09B2 \u0986\u09AA\u09A8\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0995\u09CB\u09A8 \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u09F7. \u098F\u0995\u099C\u09A8 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u0995\u09C7 \u09AC\u09C7\u099B\u09C7 \u09A8\u09C7\u0993\u09AF\u09BC\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0995\u09AF\u09BC\u09C7\u0995\u099F\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u09B8\u0995\u09CD\u09B7\u09AE \u09B9\u09A4\u09C7 \u09B9\u09AC\u09C7 \u098F\u09AC\u0982 \u098F\u0995\u09BE\u09A7\u09BF\u0995 \u09A7\u09B0\u09A3\u09C7\u09B0 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09BE\u099C\u09BE\u09B0 \u0996\u09CB\u09B2\u09BE \u09B0\u09BE\u0996\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u099F\u09BF \u098F\u0995 \u09A7\u09B0\u09A3\u09C7\u09B0 \u09AD\u09BE\u09B0\u09B8\u09BE\u09AE\u09CD\u09AF \u09A5\u09BE\u0995\u09BE \u09A6\u09B0\u0995\u09BE\u09B0\u0964.</p>
  <p>\u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09B8\u09CD\u09B2\u099F\u0997\u09C1\u09B2\u09BF \u09AC\u09BE\u099C\u09BE\u09B0\u09C7\u09B0 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09A6\u09C7\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u09AA\u09B0\u09AE \u09AA\u09CD\u09B0\u09BF\u09AF\u09BC, \u098F\u09AC\u0982 \u098F\u0995\u099F\u09BF \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u099C\u09C1\u09AF\u09BC\u09BE \u09B8\u09BE\u0987\u099F\u09C7\u09B0 \u098F\u0995\u099F\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8 \u09A5\u09C7\u0995\u09C7 \u0986\u09AA\u09A8\u09BF \u0995\u09C0 \u0986\u09B6\u09BE \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09B8\u09C7 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u0986\u09AE\u09B0\u09BE \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u098F\u0995\u099F\u09C1 \u09AC\u09B2\u09BF\u09F7.</p>
  <p>\u098F\u0995\u099F\u09BF \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8\u09C7 \u09AF\u09C7 \u0995\u09CB\u09A8\u09CB \u0996\u09C7\u09B2\u09BE \u09B8\u09AE\u09CD\u09AA\u09C2\u09B0\u09CD\u09A3\u09B0\u09C2\u09AA\u09C7 \u098F\u09B2\u09CB\u09AE\u09C7\u09B2\u09CB \u09B9\u09AC\u09C7, \u09A0\u09BF\u0995 \u0995\u09AF\u09BC\u09C7\u09A8 \u099F\u09B8 \u0995\u09B0\u09BE\u09B0 \u09AE\u09A4\u09CB. \u09AF\u09C7 \u0995\u09AE\u09CD\u09AA\u09BF\u0989\u099F\u09BE\u09B0 \u09AA\u09CD\u09B0\u09CB\u0997\u09CD\u09B0\u09BE\u09AE\u099F\u09BF \u0997\u09C7\u09AE\u099F\u09BF \u09A8\u09BF\u09AF\u09BC\u09A8\u09CD\u09A4\u09CD\u09B0\u09A3 \u0995\u09B0\u09C7 \u09A4\u09BE \u09AA\u09CD\u09B0\u09A5\u09AE \u09B8\u09BE\u09B0\u09BF\u09A4\u09C7 \u098F\u0995\u099F\u09BF \u098F\u09B2\u09CB\u09AE\u09C7\u09B2\u09CB \u09AA\u09CD\u09B0\u09A4\u09C0\u0995 \u09A8\u09BF\u09B0\u09CD\u09AC\u09BE\u099A\u09A8 \u0995\u09B0\u09C7, \u09A4\u09BE\u09B0\u09AA\u09B0\u09C7 \u09A6\u09CD\u09AC\u09BF\u09A4\u09C0\u09AF\u09BC\u099F\u09BF\u0964. \u09AA\u09C7\u09AC\u09CD\u09AF\u09BE\u0995 \u09B9\u09B2 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u0995\u09C7 \u0997\u09A1\u09BC\u09C7 \u0995\u09A4 \u09B6\u09A4\u09BE\u0982\u09B6 \u099F\u09BE\u0995\u09BE \u09AB\u09C7\u09B0\u09A4 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE \u09B9\u09AF\u09BC\u0964. \u0996\u09C7\u09B2\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BF \u09B8\u09CD\u09AA\u09BF\u09A8 \u0986\u0997\u09C7\u09B0 \u0996\u09C7\u09B2\u09BE\u09B0 \u09AE\u09A4\u09CB\u0987 \u099C\u09AF\u09BC \u09AC\u09BE \u09B9\u09BE\u09B0\u09BE\u09B0 \u09B8\u09C1\u09AF\u09CB\u0997 \u09B0\u09AF\u09BC\u09C7\u099B\u09C7; \u09B6\u09C7\u09B7 \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F\u099F\u09BF \u0995\u09A4\u0995\u09CD\u09B7\u09A3\u09C7 \u09AA\u09B0\u09BF\u09B6\u09CB\u09A7 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09BF\u09B2 \u09AC\u09BE \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8\u099F\u09BF "\u0997\u09B0\u09AE" \u09AC\u09BE "\u09A0\u09BE\u09A8\u09CD\u09A1\u09BE" \u0995\u09BF\u09A8\u09BE \u09A4\u09BE \u09AC\u09B2\u09BE\u09B0 \u0995\u09BF\u099B\u09C1 \u09A8\u09C7\u0987\u09F7</p>
  <p>80 \u098F\u09B0 \u09A6\u09B6\u0995\u09C7, \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8\u0997\u09C1\u09B2\u09BF \u0996\u09C1\u09AC \u099C\u09A8\u09AA\u09CD\u09B0\u09BF\u09AF\u09BC \u09B9\u09AF\u09BC\u09C7 \u0993\u09A0\u09C7 \u098F\u09AC\u0982 \u098F\u09AE\u09A8\u0995\u09BF \u0995\u09CD\u09B0\u09CD\u09AF\u09BE\u09AA\u09B8 \u098F\u09AC\u0982 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u099C\u09CD\u09AF\u09BE\u0995\u09C7\u09B0 \u09AE\u09A4\u09CB \u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF\u0995\u09C7\u0993 \u099B\u09BE\u09A1\u09BC\u09BF\u09AF\u09BC\u09C7 \u09AF\u09BE\u09AF\u09BC\u0964. \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8 \u098F\u09AC\u0982 \u09AD\u09BF\u09A1\u09BF\u0993 \u099C\u09C1\u099C\u09C1 \u098F\u0996\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09B0 \u09B2\u09BE\u09AD\u09C7\u09B0 70 \u09B6\u09A4\u09BE\u0982\u09B6\u09C7\u09B0\u0993 \u09AC\u09C7\u09B6\u09BF\u0964. \u098F\u0996\u09A8 \u09AF\u09C7\u09B9\u09C7\u09A4\u09C1 \u0986\u09AE\u09B0\u09BE \u0985\u09A8\u09B2\u09BE\u0987\u09A8\u09C7 \u099A\u09B2\u09C7 \u098F\u09B8\u09C7\u099B\u09BF, \u098F\u099F\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u098F\u09AC\u0982 \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u098F\u09AC\u0982 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u09AA\u09A6\u09CD\u09A7\u09A4\u09BF \u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09C7 \u09A8\u09BE \u098F\u09AE\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09A5\u09C7\u0995\u09C7 \u09B2\u09BE\u09AD \u0985\u09AC\u09CD\u09AF\u09BE\u09B9\u09A4 \u09B0\u09BE\u0996\u09C7\u0964. \u098F\u099F\u09BF \u098F\u0995\u099F\u09BF \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3 \u0995\u09BE\u09B0\u09A3\u09C7: \u09AC\u09A1\u09BC \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F\u0964. \u09AF\u0996\u09A8 \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8\u0997\u09C1\u09B2\u09BF \u09A1\u09BF\u099C\u09BF\u099F\u09BE\u0987\u099C\u09A1 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09BF\u09B2, \u09A4\u0996\u09A8 \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F\u0995\u09C7 \u0995\u09AE \u0998\u09A8 \u0998\u09A8 \u099C\u09AF\u09BC \u0995\u09B0\u09BE \u09B8\u09AE\u09CD\u09AD\u09AC \u09B9\u09AF\u09BC\u09C7\u099B\u09BF\u09B2, \u09AF\u09BE\u09B0 \u09AE\u09BE\u09A8\u09C7 \u09B9\u09B2 \u09AF\u09C7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8\u09C7 \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F \u0986\u09AA\u09A8\u09BF \u09AA\u09CD\u09B0\u09A5\u09AE\u09AC\u09BE\u09B0 \u099C\u09BF\u09A4\u09C7\u099B\u09BF\u09B2\u09C7\u09A8 \u09A4\u0996\u09A8 \u09AC\u09A1\u09BC \u09B9\u09AF\u09BC\u09C7 \u0997\u09BF\u09AF\u09BC\u09C7\u099B\u09BF\u09B2\u0964. \u098F\u09AC\u0982 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09B0\u09BE \u09AC\u09A1\u09BC \u099C\u09CD\u09AF\u09BE\u0995\u09AA\u099F \u09AA\u099B\u09A8\u09CD\u09A6 \u0995\u09B0\u09C7! \u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u098F\u0995\u099F\u09BF \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u099C\u09CD\u09AF\u09BE\u0995 \u099F\u09C7\u09AC\u09BF\u09B2\u09C7 5 \u09A1\u09B2\u09BE\u09B0\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0996\u09C7\u09B2\u09C7\u09A8, \u0986\u09AA\u09A8\u09BF \u09B8\u09B0\u09CD\u09AC\u09BE\u09A7\u09BF\u0995 7.5 \u09A1\u09B2\u09BE\u09B0 \u099C\u09BF\u09A4\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u098F\u0995\u099F\u09BF \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8\u09C7 3 \u09A1\u09B2\u09BE\u09B0 \u09A6\u09BF\u09AF\u09BC\u09C7 \u0996\u09C7\u09B2\u09C7\u09A8, \u0986\u09AA\u09A8\u09BF \u098F\u0995\u09AC\u09BE\u09B0\u09C7 \u0995\u09AF\u09BC\u09C7\u0995 \u09B9\u09BE\u099C\u09BE\u09B0 \u09AC\u09BE \u09AE\u09BF\u09B2\u09BF\u09AF\u09BC\u09A8 \u09A1\u09B2\u09BE\u09B0 \u099C\u09BF\u09A4\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8, \u09A4\u09AC\u09C7 \u098F\u099F\u09BF \u09B6\u09C1\u09A7\u09C1\u09AE\u09BE\u09A4\u09CD\u09B0 \u09AF\u09A6\u09BF \u09A4\u09C1\u09AE\u09BF \u09AD\u09BE\u0997\u09CD\u09AF\u09AC\u09BE\u09A8. \u0986\u09AE\u09B0\u09BE \u0986\u0997\u09C7\u0987 \u09AC\u09B2\u09C7\u099B\u09BF, \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF\u0995\u09C7 \u09AC\u09BF\u09A8\u09CB\u09A6\u09A8 \u09B9\u09BF\u09B8\u09BE\u09AC\u09C7 \u09A6\u09C7\u0996\u09A4\u09C7 \u09B9\u09AC\u09C7 \u098F\u09AC\u0982 \u09A6\u09CD\u09B0\u09C1\u09A4 \u09AC\u09C7\u09A4\u09A8\u09C7\u09B0 \u09A6\u09BF\u09A8 \u09A8\u09AF\u09BC\u0964.</p>
  <p>\u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09A4\u09BE\u09A6\u09C7\u09B0 \u099C\u09A8\u09AA\u09CD\u09B0\u09BF\u09AF\u09BC\u09A4\u09BE \u09B8\u09A4\u09CD\u09A4\u09CD\u09AC\u09C7\u0993, \u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE \u09AC\u09A8\u09BE\u09AE \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8 \u0996\u09C7\u09B2\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09A4\u09BF\u09A8\u099F\u09BF \u09AA\u09CD\u09B0\u09A7\u09BE\u09A8 \u09B8\u09AE\u09B8\u09CD\u09AF\u09BE \u09B0\u09AF\u09BC\u09C7\u099B\u09C7\u0964. \u09AA\u09CD\u09B0\u09A5\u09AE\u09A4, \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF \u09AA\u09CD\u09B0\u09A4\u09BF\u099F\u09BF \u0997\u09C7\u09AE\u09C7 \u09AF\u09C7 \u09AA\u09CD\u09B0\u09A4\u09BF\u0995\u09C2\u09B2\u09A4\u09BE\u0997\u09C1\u09B2\u09BF \u09B0\u09BE\u0996\u09C7 \u09B8\u09C7 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u09B8\u09B0\u09CD\u09AC\u09A6\u09BE \u0996\u09CB\u09B2\u09BE \u09A5\u09BE\u0995\u09C7 \u09A8\u09BE \u098F\u09AC\u0982 \u098F\u09B0 \u0985\u09B0\u09CD\u09A5 \u09B9\u09B2 \u098F\u099F\u09BF \u099C\u09C7\u09A4\u09BE\u09B0 \u09B8\u09AE\u09CD\u09AD\u09BE\u09AC\u09A8\u09BE \u0995\u09A4\u099F\u09BE \u09A4\u09BE \u099C\u09BE\u09A8\u09BE \u0995\u09A0\u09BF\u09A8\u0964. \u09A6\u09CD\u09AC\u09BF\u09A4\u09C0\u09AF\u09BC\u09A4, \u098F\u0987 \u0997\u09CB\u09AA\u09A8 \u09AA\u09CD\u09B0\u09A4\u09BF\u0995\u09C2\u09B2\u09A4\u09BE \u09AF\u09BE\u0987 \u09B9\u09CB\u0995 \u09A8\u09BE \u0995\u09C7\u09A8, \u098F\u0997\u09C1\u09B2\u09BF \u09AA\u09CD\u09B0\u09BE\u09AF\u09BC\u09B6\u0987 \u09AD\u09C1\u09B2 \u098F\u09AC\u0982 \u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE\u09C7\u09B0 \u099A\u09C7\u09AF\u09BC\u09C7 \u0996\u09BE\u09B0\u09BE\u09AA \u09AF\u09C7\u09AE\u09A8 \u0995\u09CD\u09B0\u09CD\u09AF\u09BE\u09AA\u09B8, \u09AC\u09CD\u09AF\u09BE\u0995\u09BE\u09B0\u09CD\u09AF\u09BE\u099F \u098F\u09AC\u0982 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u099C\u09CD\u09AF\u09BE\u0995\u0964. \u09A4\u09C3\u09A4\u09C0\u09AF\u09BC\u09A4, \u09B8\u09CD\u09B2\u099F \u09AE\u09C7\u09B6\u09BF\u09A8\u0997\u09C1\u09B2\u09BF \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0997\u09C7\u09AE\u09C7\u09B0 \u09A4\u09C1\u09B2\u09A8\u09BE\u09AF\u09BC \u0985\u09A8\u09C7\u0995 \u09A6\u09CD\u09B0\u09C1\u09A4 \u099A\u09B2\u09C7 \u098F\u09AC\u0982 \u098F\u0987\u09AD\u09BE\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u0985\u09B2\u09CD\u09AA \u09B8\u09AE\u09AF\u09BC\u09C7\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u0985\u09A8\u09C7\u0995 \u099F\u09BE\u0995\u09BE \u09B9\u09BE\u09B0\u09BE\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964.</p>
  <p>\u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u09B9\u09B2 \u09AA\u09B0\u09AC\u09B0\u09CD\u09A4\u09C0 \u09AC\u09A1\u09BC \u099C\u09BF\u09A8\u09BF\u09B8, \u09A4\u09BE\u0987 \u0986\u09B8\u09C1\u09A8 \u098F\u0987 \u09A7\u09B0\u09A8\u09C7\u09B0 \u0997\u09C7\u09AE \u09A5\u09C7\u0995\u09C7 \u0986\u09AA\u09A8\u09BF \u0995\u09C0 \u0986\u09B6\u09BE \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09B8\u09C7 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u0995\u09A5\u09BE \u09AC\u09B2\u09BF \u098F\u09AC\u0982 \u09B8\u09C7\u0996\u09BE\u09A8\u09C7 \u09A8\u09A4\u09C1\u09A8\u09A6\u09C7\u09B0 \u09A4\u09BE\u09B0\u09BE \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09B8\u09CD\u09B2\u099F\u09C7 \u09A4\u09BE\u09A6\u09C7\u09B0 \u0995\u09B7\u09CD\u099F\u09BE\u09B0\u09CD\u099C\u09BF\u09A4 \u0985\u09B0\u09CD\u09A5 \u09AC\u09CD\u09AF\u09AF\u09BC \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u0995\u09C7\u09A8\u09BE\u09B0 \u0986\u0997\u09C7 \u09A6\u09CD\u09B0\u09C1\u09A4 \u09B6\u09C7\u0996\u09BE\u09B0 \u09B8\u09C1\u09AF\u09CB\u0997 \u09A6\u09C7\u09AF\u09BC \u098F\u09AC\u0982 \u09A6\u09CD\u09B0\u09C1\u09A4 \u09AA\u09B0\u09BF\u09B6\u09CB\u09A7\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0985\u09A8\u09CD\u09AF\u09BE\u09A8\u09CD\u09AF \u0997\u09C7\u09AE\u0964.</p>
  <p>\u09AC\u09C7\u09B6\u09BF\u09B0\u09AD\u09BE\u0997 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09C7, \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u098F\u09AE\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0996\u09C7\u09B2\u09C7\u09A8 \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u09B8\u09C7\u0997\u09C1\u09B2\u09BF \u09A8\u09C7\u0987, \u09A4\u09BE\u09B9\u09B2\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u098F\u099F\u09BF \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09C7 \u098F\u09AE\u09A8 \u0985\u09A8\u09CD\u09AF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09CB\u0981\u099C\u09BE\u09B0 \u0995\u09A5\u09BE \u09AC\u09BF\u09AC\u09C7\u099A\u09A8\u09BE \u0995\u09B0\u09BE \u0989\u099A\u09BF\u09A4\u0964.</p>
  <p>\u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE \u0996\u09C7\u09B2\u09A4\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0985\u09B0\u09CD\u09A5\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0996\u09C7\u09B2\u09A4\u09C7 \u09B9\u09AC\u09C7 \u09A8\u09BE\u0964. \u0985\u09A8\u09C7\u0995 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09AC\u09BF\u09A8\u09BE\u09AE\u09C2\u09B2\u09CD\u09AF\u09C7 \u0996\u09C7\u09B2\u09BE \u09AC\u09BE \u09A1\u09C7\u09AE\u09CB \u0996\u09C7\u09B2\u09BE \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09C7, \u09A4\u09BE\u0987 \u0986\u09AA\u09A8\u09BF \u0986\u09B8\u09B2 \u099F\u09BE\u0995\u09BE \u099C\u09AE\u09BE \u0995\u09B0\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964. \u09A6\u09C0\u09B0\u09CD\u0998\u09AE\u09C7\u09AF\u09BC\u09BE\u09A6\u09C7, \u098F\u099F\u09BF \u0995\u09BF\u099B\u09C1\u099F\u09BE \u09AC\u09BF\u09B0\u0995\u09CD\u09A4\u09BF\u0995\u09B0 \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7, \u09A4\u09AC\u09C7 \u09AA\u09B0\u09AC\u09B0\u09CD\u09A4\u09C0 \u09A4\u09BE\u09B0\u09BF\u0996\u09C7 \u09A8\u0997\u09A6 \u099C\u09AE\u09BE \u0995\u09B0\u09BE\u09B0 \u09B8\u09AE\u09CD\u09AA\u09C2\u09B0\u09CD\u09A3 \u09B8\u09C1\u09AF\u09CB\u0997 \u09B0\u09AF\u09BC\u09C7\u099B\u09C7\u0964.</p>
  <p>\u098F\u0995\u099F\u09BF \u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE\u09C7 \u0986\u09AA\u09A8\u09BF \u0995\u09A4\u099F\u09BE \u09AC\u09BE\u099C\u09BF \u09A7\u09B0\u09AC\u09C7\u09A8 \u09A4\u09BE \u0986\u09AA\u09A8\u09BE\u09B0 \u0989\u09AA\u09B0 \u09A8\u09BF\u09B0\u09CD\u09AD\u09B0 \u0995\u09B0\u09C7, \u09A4\u09AC\u09C7 \u0985\u0982\u09B6\u0997\u09CD\u09B0\u09B9\u09A3 \u0995\u09B0\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u098F\u099F\u09BF \u09AA\u09CD\u09B0\u09BE\u09AF\u09BC\u09B6\u0987 \u098F\u0995\u099F\u09BF \u09B8\u09B0\u09CD\u09AC\u09A8\u09BF\u09AE\u09CD\u09A8 \u09AC\u09BE\u099C\u09BF\u0964. \u098F\u099F\u09BF \u09AC\u09BF\u09AD\u09BF\u09A8\u09CD\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B8\u09BE\u0987\u099F\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09BF\u09A4 \u09B9\u09AF\u09BC, \u09A4\u09BE\u0987 \u0986\u09AA\u09A8\u09BF \u09AF\u0996\u09A8 \u0996\u09C7\u09B2\u09AC\u09C7\u09A8 \u098F\u09AE\u09A8 \u098F\u0995\u099F\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09AF\u09BC\u09C7\u099B\u09C7\u09A8 \u09A4\u0996\u09A8 \u09A8\u09BF\u09B0\u09CD\u09A6\u09CD\u09AC\u09BF\u09A7\u09BE\u09AF\u09BC \u09A8\u09BF\u099C\u09C7\u0995\u09C7 \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE \u0995\u09B0\u09C1\u09A8\u09F7.</p>
  <p>\u0985\u09A8\u09B2\u09BE\u0987\u09A8 Blackjack \u09AF\u09BE\u0995\u09C7 \u098F\u0995\u09C1\u09B6\u0993 \u09AC\u09B2\u09BE \u09B9\u09AF\u09BC, \u098F\u0995\u099F\u09BF \u099F\u09C7\u09AC\u09BF\u09B2 \u0997\u09C7\u09AE \u09AF\u09BE \u09AC\u09C7\u09B6\u09BF\u09B0\u09AD\u09BE\u0997 \u09B2\u09CB\u0995\u09C7\u09B0\u09BE \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AF\u09C1\u0995\u09CD\u09A4\u0964. \u0986\u099C\u0995\u09BE\u09B2, \u0986\u09AA\u09A8\u09BF \u09AC\u09B8\u09BE\u09B0 \u0998\u09B0\u09C7 \u0998\u09B0\u09C7 \u09AC\u09B8\u09C7 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u099C\u09CD\u09AF\u09BE\u0995 \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8, \u09AF\u09A4\u0995\u09CD\u09B7\u09A3 \u09A8\u09BE \u0986\u09AA\u09A8\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8\u09C7 \u09B8\u0982\u09AF\u09CB\u0997 \u0995\u09B0\u09C7\u09A8 \u098F\u09AC\u0982 \u098F\u0995\u099F\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u099C\u09AE\u09BE \u0995\u09B0\u09C7\u09A8\u0964. \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF\u09B0 \u09B8\u09AE\u09B8\u09CD\u09A4 \u09AA\u09CD\u09B0\u09BE\u09A5\u09AE\u09BF\u0995 \u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u0995\u09BE\u09B0\u09C0\u09A6\u09C7\u09B0 \u09A4\u09BE\u09A6\u09C7\u09B0 \u09AA\u09CB\u09B0\u09CD\u099F\u09AB\u09CB\u09B2\u09BF\u0993\u09A4\u09C7 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u099C\u09CD\u09AF\u09BE\u0995 \u09B0\u09AF\u09BC\u09C7\u099B\u09C7\u0964.</p>
  <p>\u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u099C\u09C1\u099C\u09C1 \u09B9\u09B2 \u098F\u0995\u099F\u09BF \u0989\u09A4\u09CD\u09A4\u09C7\u099C\u09A8\u09BE\u09AA\u09C2\u09B0\u09CD\u09A3 \u0995\u09BE\u09B0\u09CD\u09A1 \u0997\u09C7\u09AE \u09AF\u09BE \u09AC\u09C7\u09B6\u09BF\u09B0\u09AD\u09BE\u0997 \u09AE\u09BE\u09A8\u09C1\u09B7\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0989\u09AA\u09AF\u09C1\u0995\u09CD\u09A4\u0964. \u09AA\u09CB\u0995\u09BE\u09B0\u09C7 \u09AD\u09BE\u09B2\u09CB \u09B9\u09A4\u09C7 \u09B8\u09AE\u09AF\u09BC \u09B2\u09BE\u0997\u09C7, \u098F\u09AC\u0982 \u099C\u09C1\u099C\u09C1 \u098F\u0995\u099F\u09BF \u09A6\u0995\u09CD\u09B7\u09A4\u09BE\u09B0 \u0996\u09C7\u09B2\u09BE \u0995\u09BF\u09A8\u09BE \u09A4\u09BE \u09A8\u09BF\u09AF\u09BC\u09C7 \u0985\u09A8\u09C7\u0995 \u0986\u09B2\u09CB\u099A\u09A8\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964. \u098F\u0996\u09BE\u09A8\u09C7, \u099C\u09C1\u099C\u09C1 \u09B6\u09BF\u09B2\u09CD\u09AA \u098F\u09AC\u0982 \u0995\u09B0\u09CD\u09A4\u09C3\u09AA\u0995\u09CD\u09B7\u09C7\u09B0 \u09A5\u09C7\u0995\u09C7 \u09AA\u09B0\u09B8\u09CD\u09AA\u09B0\u09AC\u09BF\u09B0\u09CB\u09A7\u09C0 \u09AE\u09A4\u09BE\u09AE\u09A4 \u0986\u099B\u09C7\u0964. \u099C\u09C1\u099C\u09C1 \u09B6\u09BF\u09B2\u09CD\u09AA, \u09A4\u09BE\u09B0 \u0985\u0982\u09B6\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF, \u09AC\u09BF\u09B6\u09CD\u09AC\u09BE\u09B8 \u0995\u09B0\u09C7 \u09AF\u09C7 \u098F\u099F\u09BF \u098F\u0995\u099F\u09BF \u09A6\u0995\u09CD\u09B7\u09A4\u09BE\u09B0 \u0996\u09C7\u09B2\u09BE\u0964. \u098F\u0995\u0987 \u09B8\u09AE\u09AF\u09BC\u09C7, \u0995\u09B0\u09CD\u09A4\u09C3\u09AA\u0995\u09CD\u09B7 \u09B2\u099F\u09BE\u09B0\u09BF \u0986\u0987\u09A8\u09C7\u09B0 \u0985\u09A7\u09C0\u09A8\u09C7 \u099C\u09C1\u099C\u09C1\u0995\u09C7 \u098F\u0995\u099F\u09BF \u0996\u09C7\u09B2\u09BE \u09B9\u09BF\u09B8\u09BE\u09AC\u09C7 \u09A6\u09C7\u0996\u09C7 \u098F\u09AC\u0982 \u09A6\u0995\u09CD\u09B7\u09A4\u09BE\u09B0 \u099A\u09C7\u09AF\u09BC\u09C7 \u09AD\u09BE\u0997\u09CD\u09AF\u09C7\u09B0 \u09AC\u09BF\u09B7\u09AF\u09BC \u09AC\u09C7\u09B6\u09BF\u0964.</p>
  <p>Video Poker \u09A1\u09BF\u099C\u09BF\u099F\u09BE\u09B2 \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u09AA\u09CD\u09B0\u09A5\u09AE \u09A6\u09BF\u0995\u09C7 \u099B\u09BF\u09B2, \u09A4\u09BE\u0987 \u098F\u099F\u09BF \u099B\u09BF\u09B2 \u09AA\u09CD\u09B0\u09A5\u09AE \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u098F\u0995\u099F\u09BF \u09AF\u09BE \u0986\u09AA\u09A8\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09B9\u09BE\u09A4\u09C7 \u0995\u09BE\u09B0\u09CD\u09A1 \u09A8\u09BE \u09A7\u09B0\u09C7\u0987 \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964. Video poker \u09AA\u09CD\u09B0\u09BE\u09AF\u09BC \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u09A8\u09BF\u09AF\u09BC\u09AE\u09BF\u09A4 \u09AA\u09CB\u0995\u09BE\u09B0 \u0989\u09AA\u09B0 \u09AD\u09BF\u09A4\u09CD\u09A4\u09BF \u0995\u09B0\u09C7, \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u0986\u09AA\u09A8\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09B9\u09BE\u09A4\u09C7 \u09B8\u09C7\u09B0\u09BE \u09AA\u09BE\u0981\u099A\u099F\u09BF \u0995\u09BE\u09B0\u09CD\u09A1 \u0996\u09C7\u09B2\u09BE.</p>
  <p>Jack, \u09AC\u09BE \u0986\u09B0\u0993 \u09AD\u09BE\u09B2, \u09AD\u09BF\u09A1\u09BF\u0993 \u099C\u09C1\u099C\u09C1 \u098F\u0995\u099F\u09BF \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3 \u09AB\u09B0\u09CD\u09AE. \u098F\u0996\u09BE\u09A8\u09C7 \u0986\u09AA\u09A8\u09BF \u098F\u0995\u099C\u09CB\u09A1\u09BC\u09BE \u099C\u09CD\u09AF\u09BE\u0995 \u09AC\u09BE \u09A4\u09BE\u09B0 \u099A\u09C7\u09AF\u09BC\u09C7 \u09AD\u09BE\u09B2\u09CB \u09AA\u09BE\u0993\u09AF\u09BC\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09B8\u09BE\u09A5\u09C7\u0987 \u099F\u09BE\u0995\u09BE \u099C\u09BF\u09A4\u09AC\u09C7\u09A8\u0964.</p>
  <p>Roulette, \u0986\u09AA\u09A8\u09BF \u0995\u09AE\u09CD\u09AC\u09BF\u09A8\u09C7\u09B6\u09A8, \u098F\u0995\u0995 \u09B8\u0982\u0996\u09CD\u09AF\u09BE, \u09B0\u0999, \u09B8\u09BE\u09B0\u09BF \u098F\u09AC\u0982 \u09AC\u09B2\u099F\u09BF \u09AC\u09BF\u099C\u09CB\u09A1\u09BC \u09AC\u09BE \u099C\u09CB\u09A1\u09BC \u09B8\u0982\u0996\u09CD\u09AF\u09BE\u09B0 \u0989\u09AA\u09B0 \u09AC\u09BE\u099C\u09BF \u09A7\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964. \u0986\u09AA\u09A8\u09BF \u09AF\u09BE \u09AC\u09BE\u099C\u09BF \u09A7\u09B0\u09C7\u099B\u09C7\u09A8 \u09A4\u09BE\u09B0 \u0989\u09AA\u09B0 \u09A8\u09BF\u09B0\u09CD\u09AD\u09B0 \u0995\u09B0\u09C7 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7\u09B0 \u09AA\u09B0\u09BF\u09AE\u09BE\u09A3 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09BF\u09A4 \u09B9\u09AF\u09BC\u0964. \u099C\u09CB\u09A1\u09BC \u09B8\u0982\u0996\u09CD\u09AF\u09BE \u098F\u09AC\u0982 \u09AC\u09BF\u099C\u09CB\u09A1\u09BC \u09B8\u0982\u0996\u09CD\u09AF\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF, \u09AA\u09B0\u09BF\u09B6\u09CB\u09A7\u09C7\u09B0 \u09AF\u09CB\u0997\u09AB\u09B2 \u09B9\u09B2 1 \u09A5\u09C7\u0995\u09C7 1, \u09AF\u09BE \u09B2\u09BE\u09B2 \u09AC\u09BE \u0995\u09BE\u09B2\u09CB \u09B0\u0999\u09C7\u09B0 \u0995\u09CD\u09B7\u09C7\u09A4\u09CD\u09B0\u09C7 \u09AA\u09CD\u09B0\u09AF\u09CB\u099C\u09CD\u09AF\u0964.</p>
  <p>\u0986\u09AA\u09A8\u09BF \u098F\u0996\u09BE\u09A8\u09C7 \u09AC\u09BE\u099C\u09BF \u09A7\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u098F\u0995\u099F\u09BF \u09AD\u09BF\u09A8\u09CD\u09A8 \u09AA\u09B0\u09BF\u09B8\u09C0\u09AE\u09BE \u0986\u099B\u09C7. \u0986\u09AA\u09A8\u09BF \u0995\u09CB\u09A8 \u0995\u09CD\u09B7\u09C7\u09A4\u09CD\u09B0\u099F\u09BF \u099A\u09AF\u09BC\u09A8 \u0995\u09B0\u09C7\u09A8 \u09A4\u09BE\u09B0 \u0989\u09AA\u09B0 \u09A8\u09BF\u09B0\u09CD\u09AD\u09B0 \u0995\u09B0\u09C7 \u0985\u09B0\u09CD\u09A5\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09BF\u09A4 \u09B9\u09AF\u09BC\u0964.</p>
  <p>Craps \u09B9\u09B2 \u098F\u0995\u099F\u09BF \u09AA\u09BE\u09B6\u09BE\u09B0 \u0996\u09C7\u09B2\u09BE \u09AF\u09C7\u0996\u09BE\u09A8\u09C7 \u098F\u0995\u099C\u09A8 \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC \u09A6\u09C1\u099F\u09BF \u09AA\u09BE\u09B6\u09BE\u09B0 \u09AB\u09B2\u09BE\u09AB\u09B2\u09C7\u09B0 \u0989\u09AA\u09B0 \u09AC\u09BE\u099C\u09BF \u09A7\u09B0\u09C7\u0964. \u098F\u099F\u09BF \u09AC\u09C7\u09B6 \u09B8\u09B9\u099C \u09B6\u09CB\u09A8\u09BE\u099A\u09CD\u099B\u09C7 \u09A4\u09AC\u09C7 \u0997\u09C7\u09AE\u099F\u09BF \u0995\u09C0\u09AD\u09BE\u09AC\u09C7 \u0996\u09C7\u09B2\u09A4\u09C7 \u09B9\u09AF\u09BC \u09A4\u09BE \u09AC\u09CB\u099D\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09B8\u09AE\u09CD\u09AD\u09AC\u09A4 \u0995\u09BF\u099B\u09C1 \u09AC\u09CD\u09AF\u09BE\u0996\u09CD\u09AF\u09BE \u09AA\u09CD\u09B0\u09AF\u09BC\u09CB\u099C\u09A8\u0964. Craps \u098F\u09B0 \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE \u09B9\u09B2 \u09AF\u09C7 \u09B6\u09C1\u09A7\u09C1\u09AE\u09BE\u09A4\u09CD\u09B0 \u09AA\u09BE\u09B6\u09BE \u0996\u09C7\u09B2\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09AA\u09CD\u09B0\u09AF\u09BC\u09CB\u099C\u09A8 \u09B9\u09AF\u09BC, \u09A4\u09BE\u0987 \u09AF\u09A4\u0995\u09CD\u09B7\u09A3 \u0986\u09AA\u09A8\u09BE\u09B0 \u0995\u09BE\u099B\u09C7 \u09A6\u09C1\u099F\u09BF \u09AA\u09BE\u09B6\u09BE \u09A5\u09BE\u0995\u09C7 \u09A4\u09A4\u0995\u09CD\u09B7\u09A3 \u0986\u09AA\u09A8\u09BF \u09B8\u09B9\u099C\u09C7\u0987 \u0995\u09CD\u09B0\u09CD\u09AF\u09BE\u09AA \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8\u0964.</p>
  <p>\u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u098F\u0995\u099F\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0997\u09BF\u09AF\u09BC\u09C7 \u09A5\u09BE\u0995\u09C7\u09A8 \u09A4\u09AC\u09C7 \u0986\u09AA\u09A8\u09BF \u099C\u09BE\u09A8\u09C7\u09A8 \u098F\u099F\u09BF \u0995\u09C7\u09AE\u09A8 \u09B2\u09BE\u0997\u09C7\u0964. \u09B2\u09BE\u0987\u09AD \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u098F\u0995\u0987 \u0985\u09A8\u09C1\u09AD\u09C2\u09A4\u09BF \u09A6\u09C7\u09AF\u09BC\u0964. \u0995\u09BF\u099B\u09C1 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7, \u0986\u09AA\u09A8\u09BF \u09AA\u09A5 \u09A7\u09B0\u09C7 \u09B9\u09CB\u09B8\u09CD\u099F\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u099A\u09CD\u09AF\u09BE\u099F \u0995\u09B0\u09BE\u09B0 \u09B8\u09C1\u09AF\u09CB\u0997 \u09AA\u09BE\u09A8. \u098F\u099F\u09BF \u0997\u09C7\u09AE\u09C7\u09B0 \u09AB\u09B2\u09BE\u09AB\u09B2\u09C7\u09B0 \u0989\u09AA\u09B0 \u09A8\u09BF\u09B0\u09CD\u09AD\u09B0 \u0995\u09B0\u09C7 \u09B2\u09BE\u0987\u09AD \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C7\u09B2\u09A4\u09C7 \u0989\u09A4\u09CD\u09A4\u09C7\u099C\u09A8\u09BE, \u0986\u09A8\u09A8\u09CD\u09A6 \u098F\u09AC\u0982 \u0995\u09BF\u099B\u09C1\u099F\u09BE \u09B9\u09A4\u09BE\u09B6\u09BE \u09AA\u09CD\u09B0\u09A6\u09BE\u09A8 \u0995\u09B0\u09C7\u0964.</p>
  <p>\u0986\u09AA\u09A8\u09BF \u09AF\u09A6\u09BF \u09B2\u09BE\u0987\u09AD \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C7\u09B2\u09A4\u09C7 \u099A\u09BE\u09A8, \u09A4\u09BE\u09B9\u09B2\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u0985\u09AC\u09B6\u09CD\u09AF\u0987 \u098F\u099F\u09BF \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09C7 \u098F\u09AE\u09A8 \u098F\u0995\u099F\u09BF \u0997\u09C7\u09AE\u09BF\u0982 \u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u0995\u09BE\u09B0\u09C0\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09A8\u09BF\u09AC\u09A8\u09CD\u09A7\u09A8 \u0995\u09B0\u09A4\u09C7 \u09B9\u09AC\u09C7\u0964. \u098F\u0995\u099F\u09BF \u09AC\u09BF\u09A6\u09C7\u09B6\u09C0 \u0997\u09C7\u09AE\u09BF\u0982 \u0995\u09CB\u09AE\u09CD\u09AA\u09BE\u09A8\u09BF\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09A8\u09BF\u09AC\u09A8\u09CD\u09A7\u09A8 \u0995\u09B0\u09BE \u09B8\u09B9\u099C, \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u09B6\u09C1\u09A7\u09C1\u09AE\u09BE\u09A4\u09CD\u09B0 \u09A8\u09BF\u099C\u09C7\u09B0 \u09B8\u09AE\u09CD\u09AA\u09B0\u09CD\u0995\u09C7 \u09A4\u09A5\u09CD\u09AF \u09A6\u09BF\u09AF\u09BC\u09C7 \u09AA\u09C2\u09B0\u09A3 \u0995\u09B0\u09C1\u09A8\u0964. \u098F\u09B0 \u09AA\u09B0\u09C7, \u0986\u09AA\u09A8\u09BF \u09AC\u09BF\u099F\u0995\u09AF\u09BC\u09C7\u09A8 \u09AC\u09BE \u0986\u09B8\u09B2 \u0985\u09B0\u09CD\u09A5\u09C7\u09B0 \u0985\u09A8\u09CD\u09AF \u09AB\u09B0\u09CD\u09AE \u099C\u09AE\u09BE \u0995\u09B0\u09C1\u09A8 \u098F\u09AC\u0982 \u0996\u09C7\u09B2\u09BE \u09B6\u09C1\u09B0\u09C1 \u0995\u09B0\u09C1\u09A8\u0964.</p>
  <p>\u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C7\u09B2\u09CB\u09AF\u09BC\u09BE\u09A1\u09BC\u09B0\u09BE \u0986\u09B6\u09BE \u0995\u09B0\u09C7 \u09AF\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B2\u09BE\u0987\u09AD \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09AC\u09C7\u0964. \u09B2\u09BE\u0987\u09AD \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C7\u09B2\u09BE \u098F\u09A4\u099F\u09BE\u0987 \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3 \u09AF\u09C7 \u09B8\u09AE\u09B8\u09CD\u09A4 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u098F\u099F\u09BF \u09A4\u09BE\u09A6\u09C7\u09B0 \u09AA\u09B0\u09BF\u09B8\u09B0\u09C7 \u09A5\u09BE\u0995\u09BE \u0989\u099A\u09BF\u09A4\u0964.</p>
  <p>\u0986\u09AA\u09A8\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8\u09C7 \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u098F\u09AE\u09A8 \u09AC\u09BF\u09AD\u09BF\u09A8\u09CD\u09A8 \u09A7\u09B0\u09A3\u09C7\u09B0 \u09B2\u09BE\u0987\u09AD \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0997\u09C7\u09AE \u09B0\u09AF\u09BC\u09C7\u099B\u09C7 \u098F\u09AC\u0982 \u09B0\u09C1\u09B2\u09C7\u099F \u098F\u09AC\u0982 \u09AC\u09CD\u09B2\u09CD\u09AF\u09BE\u0995\u099C\u09CD\u09AF\u09BE\u0995 \u09B9\u09B2 \u09B2\u09BE\u0987\u09AD \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF\u09B0 \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3 \u09B0\u09C2\u09AA\u0964. \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u09AE\u09A8\u09CB\u09AA\u09B2\u09BF\u09B0 \u09AE\u09A4\u09CB \u0997\u09C7\u09AE\u0993 \u09B0\u09AF\u09BC\u09C7\u099B\u09C7 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u098F\u0995\u099C\u09A8 \u0995\u09CB\u099F\u09BF\u09AA\u09A4\u09BF \u09B9\u09AF\u09BC\u09C7 \u09AF\u09BE\u09AC\u09C7\u09A8 \u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u09B2\u09BE\u0987\u09AD \u0996\u09C7\u09B2\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u098F\u09AE\u09A8 \u0995\u09BE\u09AF\u09BC\u09A6\u09BE \u0995\u09B0\u09C7 \u0998\u09C1\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09AC\u09C7\u09A8\u0964.</p>
  <p>\u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF\u09B0 \u09A8\u09BF\u09B0\u09CD\u09AC\u09BE\u099A\u09A8 \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3\u09A4 \u09AC\u09BF\u09B6\u09BE\u09B2 \u09B9\u09AF\u09BC, \u09A4\u09AC\u09C7 \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u099C\u09BE\u09A8\u09A4\u09C7 \u09B9\u09AC\u09C7 \u09AF\u09C7 \u098F\u099F\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09A5\u09C7\u0995\u09C7 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u09AA\u09B0\u09BF\u09AC\u09B0\u09CD\u09A4\u09BF\u09A4 \u09B9\u09AF\u09BC, \u09A4\u09BE\u0987 \u0986\u09AA\u09A8\u09BF \u09B8\u09AC\u09B8\u09AE\u09AF\u09BC \u098F\u0995\u0987 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u09AC\u09BF\u09AD\u09BF\u09A8\u09CD\u09A8 \u0995\u09CD\u09B0\u09BF\u09AA\u09CD\u099F\u09CB \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B8\u09BE\u0987\u099F\u09C7 \u0998\u09C1\u09B0\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964. \u098F\u0987 \u0995\u09BE\u09B0\u09A3\u09C7\u0987 \u0986\u09AE\u09B0\u09BE \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u099F\u09BF\u09AA\u09B8 \u09A6\u09C7\u0993\u09AF\u09BC\u09BE\u09B0 \u09B8\u09AE\u09AF\u09BC \u09AC\u09B2\u09C7\u099B\u09BF\u09B2\u09BE\u09AE \u0995\u09CB\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C7\u09B2\u09A4\u09C7 \u09B9\u09AC\u09C7, \u09AC\u09BE \u0995\u09CB\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0996\u09C7\u09B2\u09A4\u09C7 \u09B9\u09AC\u09C7 \u09A8\u09BE, \u0995\u09BF\u09A8\u09CD\u09A4\u09C1 \u0986\u09AA\u09A8\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u09AF\u09C7 \u0997\u09C7\u09AE\u0997\u09C1\u09B2\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09A4\u09BE \u09A6\u09C7\u0996\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09AA\u09A8\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u09A8\u09BF\u0996\u09C1\u0981\u09A4 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0995\u09C0\u09AD\u09BE\u09AC\u09C7 \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09BE\u09AC\u09C7\u09A8\u0964.</p>
  <p>\u098F\u09AC\u0982 \u0986\u09AA\u09A8\u09BF \u0995\u09BF \u09A7\u09B0\u09A8\u09C7\u09B0 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09A4\u09BE \u099A\u09C7\u0995 \u0995\u09B0\u09A4\u09C7 \u09AD\u09C1\u09B2\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964. \u09B8\u09AE\u09B8\u09CD\u09A4 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u09AC\u09CB\u09A8\u09BE\u09B8 \u09A6\u09C7\u09AF\u09BC \u09A8\u09BE, \u09A4\u09AC\u09C7 \u09A4\u09BE\u09B0\u09BE \u0986\u09AA\u09A8\u09BE\u0995\u09C7 \u09AA\u09C1\u09A8\u09B0\u09BE\u09AF\u09BC \u09B2\u09CB\u09A1 \u09AC\u09CB\u09A8\u09BE\u09B8 \u09B8\u09B0\u09AC\u09B0\u09BE\u09B9 \u0995\u09B0\u09AC\u09C7\u0964. \u09B8\u09C1\u09A4\u09B0\u09BE\u0982, \u0986\u09AA\u09A8\u09BF \u09AA\u09C1\u09A8\u09B0\u09BE\u09AF\u09BC \u09B2\u09CB\u09A1 \u09AC\u09CB\u09A8\u09BE\u09B8 \u098F\u09AC\u0982 \u0995\u09CB\u09A8 \u09A1\u09BF\u09AA\u09CB\u099C\u09BF\u099F \u09AC\u09CB\u09A8\u09BE\u09B8 \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u09B6\u09C1\u09B0\u09C1 \u0995\u09B0\u09BE\u09B0 \u0986\u0997\u09C7 \u09AF\u09A5\u09C7\u09B7\u09CD\u099F \u09AD\u09BE\u09B2 \u09AA\u09B0\u09C0\u0995\u09CD\u09B7\u09BE \u09A8\u09BE \u0995\u09B0\u09C7\u09A8\u0964. \u098F\u09AC\u0982 \u09AF\u09A6\u09BF \u0986\u09AA\u09A8\u09BF \u09AD\u09BE\u0997\u09CD\u09AF\u09AC\u09BE\u09A8 \u09B9\u09A8, \u0986\u09AA\u09A8\u09BF \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u0997\u09C1\u09B2\u09BF \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09AF\u09BE \u09AA\u09CD\u09B0\u09A4\u09BF\u09A6\u09BF\u09A8\u09C7\u09B0 \u0995\u09CD\u09AF\u09BE\u09B6\u09AC\u09CD\u09AF\u09BE\u0995 \u09A6\u09C7\u09AF\u09BC\u0964.</p>
  

  <h2>\u0986\u09AE\u09BF \u0995\u09BF \u09AE\u09CB\u09AC\u09BE\u0987\u09B2 \u09AC\u09BE \u099F\u09CD\u09AF\u09BE\u09AC\u09B2\u09C7\u099F \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 \u09AA\u09BE\u09B0\u09BF?</h2>
  <p>\u09A7\u09B0\u09C1\u09A8 \u0986\u09AA\u09A8\u09BF \u09B6\u09C0\u09B0\u09CD\u09B7 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB\u09A4\u09C7 \u0996\u09C7\u09B2\u09A4\u09C7 \u099A\u09BE\u09A8\u0964. \u09B8\u09C7\u0995\u09CD\u09B7\u09C7\u09A4\u09CD\u09B0\u09C7, \u0986\u09AA\u09A8\u09BF \u099A\u09BE\u09A8 \u09AF\u09C7 \u09B8\u09C7\u0997\u09C1\u09B2\u09BF \u09B8\u09AC\u0987 \u09AE\u09CB\u09AC\u09BE\u0987\u09B2 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u09B9\u09CB\u0995, \u09B6\u09C1\u09A7\u09C1\u09AE\u09BE\u09A4\u09CD\u09B0 \u0996\u09C7\u09B2\u09BE\u09B0 \u09AC\u09BF\u09B6\u09C1\u09A6\u09CD\u09A7 \u0986\u09A8\u09A8\u09CD\u09A6\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09AF\u0996\u09A8\u0987 \u098F\u09AC\u0982 \u09AF\u09C7\u0996\u09BE\u09A8\u09C7\u0987 \u09A5\u09BE\u0995\u09C1\u09A8 \u0986\u09AA\u09A8\u09BF \u09AF\u09C7\u09A6\u09BF\u09A8 \u0996\u09C7\u09B2\u09A4\u09C7 \u099A\u09BE\u09A8\u0964.</p>
  <p>\u09AE\u09CB\u09AC\u09BE\u0987\u09B2 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0985\u09AB\u09BE\u09B0 \u0995\u09B0\u09C7 \u098F\u09AE\u09A8 \u09AC\u09C7\u099F\u09BF\u0982 \u09B8\u09BE\u0987\u099F\u0997\u09C1\u09B2\u09BF \u09AE\u09CB\u09AC\u09BE\u0987\u09B2 \u0995\u09CD\u09AF\u09BE\u09B8\u09BF\u09A8\u09CB \u0985\u09AB\u09BE\u09B0 \u09A8\u09BE \u0995\u09B0\u09BE\u09B0 \u099A\u09C7\u09AF\u09BC\u09C7 \u09A6\u09BF\u09A8\u09C7 \u09AC\u09C7\u09B6\u09BF \u09B9\u09BF\u099F \u09AA\u09BE\u099A\u09CD\u099B\u09C7\u09F7. \u0986\u09AE\u09B0\u09BE \u09B8\u09AC\u09BE\u0987 \u099C\u09BE\u09A8\u09BF \u09AF\u09C7 \u0995\u09C7\u0989 \u09A4\u09BE\u09A6\u09C7\u09B0 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u099C\u09C1\u09AF\u09BC\u09BE \u0996\u09C7\u09B2\u09BE\u09B0 \u099C\u09A8\u09CD\u09AF \u0986\u09B0 \u09B2\u09CD\u09AF\u09BE\u09AA\u099F\u09AA\u09C7\u09B0 \u09B8\u09BE\u09AE\u09A8\u09C7 \u09AC\u09B8\u09A4\u09C7 \u099A\u09BE\u09AF\u09BC \u09A8\u09BE\u0964. \u09B8\u09AC\u099A\u09C7\u09AF\u09BC\u09C7 \u09AD\u09BE\u09B2\u09CB \u09B9\u09B2 \u09AF\u09C7 \u0986\u09AA\u09A8\u09BF \u09B8\u09AE\u09B8\u09CD\u09A4 \u09AE\u09C7\u09B2\u09BE \u0997\u09C7\u09AE \u098F\u09AC\u0982 \u099A\u09AE\u09CE\u0995\u09BE\u09B0 \u09B8\u09CD\u09AC\u09BE\u0997\u09A4 \u09AC\u09CB\u09A8\u09BE\u09B8 \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09C7\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u09A8 \u09AF\u09BE \u0986\u09AA\u09A8\u09BF \u09B8\u09BE\u09A7\u09BE\u09B0\u09A3\u09A4 \u09B2\u09CD\u09AF\u09BE\u09AA\u099F\u09AA \u09A5\u09C7\u0995\u09C7 \u0996\u09C7\u09B2\u09C7\u09A8\u0964.</p>
</div>`;
